{"command": "cat <<'EOF' > /tmp/shim/git
#!/bin/bash
echo "GIT: $*" >> /tmp/shim/log.txt
cmd="$*"
rules=/tmp/shim/rules.txt
if [ -f "$rules" ]; then
  while IFS='|' read -r pat mode; do
    [ -z "$pat" ] && continue
    case "$cmd" in
      *"$pat"*) ;;
      *) continue;;
    esac
    case "$mode" in
      dropfirst) /usr/bin/git "$@" | tail -n +2; exit ${PIPESTATUS[0]} ;;
      dropall)   /usr/bin/git "$@" >/dev/null; exit 0 ;;
      empty)     :; exit 0 ;;
      fail)      echo "shim: simulated failure" >&2; exit 128 ;;
      prefix)    echo "BOGUS"; /usr/bin/git "$@"; exit ${PIPESTATUS[0]} ;;
      striphead) /usr/bin/git "$@" | sed 's/^ref: //'; exit ${PIPESTATUS[0]} ;;
      rembranch) /usr/bin/git "$@" | sed 's|^refs/remotes/||'; exit ${PIPESTATUS[0]} ;;
      emptyline) /usr/bin/git "$@" | sed '2i\'; exit ${PIPESTATUS[0]} ;;
      tailfirst) /usr/bin/git "$@" | tail -1; exit ${PIPESTATUS[0]} ;;
    esac
  done < "$rules"
fi
exec /usr/bin/git "$@"
EOF
chmod +x /tmp/shim/git; cd /tmp/lr21
for r in "branch --format %(refname) --remote --merged|prefix" "branch --format %(refname) --merged|prefix" "worktree list|prefix" "rev-list|prefix"; do
  echo "=== rule [$r] ==="; echo "$r" > /tmp/shim/rules.txt; rm -f /tmp/shim/log.txt
  PATH=/tmp/shim:$PATH /workspace/executable --dry-run >/tmp/o.txt 2>/tmp/e.txt; echo "EXIT $?"; cat /tmp/o.txt|tail -3; echo "--ERR--"; cat /tmp/e.txt
done"}

