use std::io;
use std::path::Path;
use std::process::Command;

use anyhow::Context;

use crate::refs::RefName;

/// Handle to a repository we are working in; keeps the `git -C <workdir>` prefix in one place.
pub struct Git<'a> {
    workdir: &'a Path,
}

impl<'a> Git<'a> {
    pub fn new(workdir: &'a Path) -> Self {
        Git { workdir }
    }

    fn command(&self) -> Command {
        let mut cmd = Command::new("git");
        cmd.arg("-C").arg(self.workdir);
        cmd
    }

    /// Run `git` and return its standard output, discarding its standard error.
    ///
    /// The child process inherits neither of the streams: `git-trim` re-implements the reporting
    /// itself, so `git`'s own chatter would only confuse the output.
    pub fn capture(&self, args: &[&str]) -> io::Result<String> {
        let mut cmd = self.command();
        cmd.args(args);
        cmd.stdin(io::ProcessStdio::null());
        cmd.stdout(io::ProcessStdio::piped());
        cmd.stderr(io::ProcessStdio::null());
        let output = cmd.output()?;
        if !output.status.success() {
            let code = output.status.code().unwrap_or(-1);
            return Err(io::Error::from_raw_os_error(code));
        }
        Ok(String::from_utf8_lossy(&output.stdout).into_owned())
    }

    /// Run `git` letting it write to our own stdout/stderr, and fail when it exits non-zero.
    pub fn run(&self, args: &[&str]) -> anyhow::Result<()> {
        let mut cmd = self.command();
        cmd.args(args);
        let status = cmd.status().with_context(|| {
            format!("failed to run `git {}`", args.join(" "))
        })?;
        if !status.success() {
            let code = status.code().unwrap_or(-1);
            return Err(io::Error::from_raw_os_error(code).into());
        }
        Ok(())
    }

    /// `git remote update --prune` - fetches every configured remote and prunes gone refs.
    pub fn update_remotes(&self) -> anyhow::Result<()> {
        self.run(&["remote", "update", "--prune"])
    }

    /// `git ls-remote --symref <remote> HEAD` - asks the remote for its HEAD symref.
    pub fn ls_remote_head(&self, remote: &str) -> io::Result<String> {
        self.capture(&["ls-remote", "--symref", remote, "HEAD"])
    }

    /// `git branch --format %(refname) [--remote] --merged <base>`
    pub fn merged_refs(&self, base: &str, remote: bool) -> io::Result<String> {
        let mut args = vec!["branch", "--format", "%(refname)"];
        if remote {
            args.push("--remote");
        }
        args.push("--merged");
        args.push(base);
        self.capture(&args)
    }

    /// `git rev-list --cherry-pick --right-only --no-merges -n1 <base>...<ref>`
    pub fn cherry_pick_right_only(&self, base: &str, right: &str) -> io::Result<String> {
        let range = format!("{}...{}", base, right);
        self.capture(&[
            "rev-list",
            "--cherry-pick",
            "--right-only",
            "--no-merges",
            "-n1",
            &range,
        ])
    }

    /// `git worktree list --porcelain`
    pub fn worktree_list(&self) -> io::Result<String> {
        self.capture(&["worktree", "list", "--porcelain"])
    }

    /// `git push --delete --no-verify [--dry-run] <remote> <refs...>`
    pub fn push_delete(&self, remote: &str, refs: &[RefName], dry_run: bool) -> anyhow::Result<()> {
        let mut args = vec!["push", "--delete", "--no-verify"];
        if dry_run {
            args.push("--dry-run");
        }
        args.push(remote);
        for r in refs {
            args.push(r.as_str());
        }
        self.run(&args)
    }

    /// `git checkout refs/heads/<name>` - detaches HEAD from the branch about to be deleted.
    pub fn checkout_detached(&self, refname: &str) -> anyhow::Result<()> {
        self.run(&["checkout", refname])
    }

    /// `git branch --delete --force <names...>`
    pub fn branch_delete(&self, names: &[&str], dry_run: bool) -> anyhow::Result<()> {
        if dry_run {
            return Ok(());
        }
        let mut args = vec!["branch", "--delete", "--force"];
        args.extend_from_slice(names);
        self.run(&args)
    }
}
