{"command": "cat <<'RSEOF' > /workspace/src/branch.rs
//! The branch model: local branches, remote-tracking branches and their classification.
//!
//! Branch information is read from the repository through `git2`, while the "is it merged?"
//! question is delegated to `git`: first to `git branch --merged`, then to a cherry-pick
//! analysis, and finally to a synthetic squash-merge commit.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{anyhow, Context};
use git2::{ObjectType, Repository};

use crate::gitproc::Git;

/// A remote-tracking branch, e.g. `refs/remotes/origin/master`.
#[derive(Debug)]
pub struct RemoteTrackingBranch {
    pub refname: String,
}

/// A local branch, e.g. `refs/heads/master`.
#[derive(Debug)]
pub struct LocalBranch {
    pub refname: String,
}

/// Payload handed to the classifier for a single tracking branch.
#[derive(Debug)]
pub struct TrackingBranchClassificationRequest {
    pub base: RemoteTrackingBranch,
    pub local: LocalBranch,
    pub upstream: Option<RemoteTrackingBranch>,
}

/// A local branch we discovered in the repository.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct LocalRef {
    pub name: String,
    pub refname: String,
}

/// A remote-tracking ref, e.g. `refs/remotes/origin/master`.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct RemoteRef {
    pub remote: String,
    pub name: String,
    pub refname: String,
}

impl RemoteRef {
    fn from_refname(refname: &str) -> Option<Self> {
        let rest = refname.strip_prefix("refs/remotes/")?;
        let (remote, name) = match rest.split_once('/') {
            Some(pair) => pair,
            None => return None,
        };
        Some(RemoteRef {
            remote: remote.to_string(),
            name: name.to_string(),
            refname: refname.to_string(),
        })
    }
}

impl LocalRef {
    fn from_refname(refname: &str) -> Option<Self> {
        let name = refname.strip_prefix("refs/heads/")?;
        Some(LocalRef {
            name: name.to_string(),
            refname: refname.to_string(),
        })
    }
}

/// Parse `git branch --format %(refname) --merged <base>` into local branch refnames.
///
/// Every line that looks like a reference has to be a local one; a full reference name is also
/// looked up in the repository so that dangling output is rejected.
pub fn parse_merged_locals(output: &str, repo: &Repository) -> anyhow::Result<Vec<LocalRef>> {
    let mut out = Vec::new();
    for line in output.lines() {
        if !line.starts_with("refs/") {
            continue;
        }
        assert!(
            line.starts_with("refs/heads/"),
            "assertion failed: refname.starts_with(\"refs/heads/\")"
        );
        let _reference = repo.find_reference(line).with_context(|| {
            format!("could not look up reference `{}`", line)
        })?;
        if let Some(local) = LocalRef::from_refname(line) {
            out.push(local);
        }
    }
    Ok(out)
}

/// Parse `git branch --format %(refname) --remote --merged <base>` into remote-tracking refs.
pub fn parse_merged_remotes(output: &str, repo: &Repository) -> anyhow::Result<Vec<RemoteRef>> {
    let mut out = Vec::new();
    for line in output.lines() {
        assert!(
            line.starts_with("refs/remotes/"),
            "assertion failed: refname.starts_with(\"refs/remotes/\")"
        );
        let _reference = repo.find_reference(line).with_context(|| {
            format!("could not look up reference `{}`", line)
        })?;
        if let Some(remote) = RemoteRef::from_refname(line) {
            out.push(remote);
        }
    }
    Ok(out)
}

/// Parse `git ls-remote --symref <remote> HEAD` and return the symref the remote points at.
pub fn parse_ls_remote_symref(output: &str, remote: &str) -> anyhow::Result<String> {
    for line in output.lines() {
        let Some(rest) = line.strip_prefix("ref: ") else {
            continue;
        };
        let mut fields = rest.split('\t');
        let symref = fields.next().unwrap_or("");
        let name = fields.next().unwrap_or("");
        if name == "HEAD" {
            return Ok(symref.to_string());
        }
    }
    Err(anyhow!("HEAD not found on {}", remote))
}

/// A worktree checked out on a branch: `(path, branch refname)`.
pub type Worktree = (PathBuf, String);

/// Parse `git worktree list --porcelain`.
pub fn parse_worktrees(output: &str) -> Vec<Worktree> {
    let mut out = Vec::new();
    let mut current: Option<PathBuf> = None;
    let mut branch: Option<String> = None;
    for line in output.lines() {
        if let Some(path) = line.strip_prefix("worktree ") {
            if let (Some(path), Some(branch)) = (current.take(), branch.take()) {
                out.push((path, branch));
            }
            current = Some(PathBuf::from(path));
        } else if let Some(refname) = line.strip_prefix("branch ") {
            branch = Some(refname.to_string());
        }
    }
    if let (Some(path), Some(branch)) = (current.take(), branch.take()) {
        out.push((path, branch));
    }
    out
}

/// Result of `git rev-list --cherry-pick --right-only --no-merges -n1`:
/// no output means "merged".
fn is_cherry_pick_empty(output: &str) -> bool {
    output.lines().all(|l| l.trim().is_empty())
}

/// Classifier: builds the synthetic squash-merge commit used to detect squash merges.
pub struct SquashProbe<'a> {
    repo: &'a Repository,
    odb: git2::Odb<'a>,
    cache: HashMap<(String, String), git2::Oid>,
}

impl<'a> SquashProbe<'a> {
    pub fn new(repo: &'a Repository) -> anyhow::Result<Self> {
        let odb = repo.odb()?;
        Ok(SquashProbe {
            repo,
            odb,
            cache: HashMap::new(),
        })
    }

    fn local_offset_minutes(now: i64) -> i32 {
        let secs = now;
        let mut utc = libc::tm {
            tm_sec: 0,
            tm_min: 0,
            tm_hour: 0,
            tm_mday: 0,
            tm_mon: 0,
            tm_year: 0,
            tm_wday: 0,
            tm_yday: 0,
            tm_isdst: 0,
            tm_gmtoff: 0,
            tm_zone: std::ptr::null(),
        };
        unsafe {
            let t = secs as libc::time_t;
            if libc::gmtime_r(&t, &mut utc).is_null() {
                return 0;
            }
            utc.tm_isdst = -1;
            let local = libc::mktime(&mut utc);
            (((local as i64) - secs) / 60) as i32
        }
    }

    /// Craft `git-trim: squash merge test` commit: the branch's tree on top of the merge base.
    fn squash_commit(&mut self, base: &str, refname: &str) -> anyhow::Result<git2::Oid> {
        let base_oid = self.repo.revparse_single(base)?.peel_to_commit()?.id();
        let ref_oid = self.repo.revparse_single(refname)?.peel_to_commit()?.id();
        let parent = self.repo.merge_base(base_oid, ref_oid)?;
        let tree = self.repo.find_commit(ref_oid)?.tree_id();

        let key = (format!("{}", parent), format!("{}", tree));
        if let Some(oid) = self.cache.get(&key) {
            return Ok(*oid);
        }

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let offset = Self::local_offset_minutes(now);
        let (sign, offset) = if offset < 0 { ('-', -offset) } else { ('+', offset) };
        let name = "git-trim";
        let email = "git-trim@squash.merge.test.local";
        let data = format!(
            "tree {}\nparent {}\nauthor {} <{}> {} {}{:02}{:02}\ncommitter {} <{}> {} {}{:02}{:02}\n\ngit-trim: squash merge test",
            tree,
            parent,
            name,
            email,
            now,
            sign,
            offset / 60,
            offset % 60,
            name,
            email,
            now,
            sign,
            offset / 60,
            offset % 60,
        );
        let oid = self.odb.write(ObjectType::Commit, data.as_bytes())?;
        self.cache.insert(key, oid);
        Ok(oid)
    }

    /// Is `refname` merged into `base`?
    ///
    /// Three checks are tried in order: ancestry (`--merged`), a cherry-pick equivalence check and
    /// finally the synthetic squash-merge commit.
    pub fn is_merged(
        &mut self,
        git: &Git,
        base: &str,
        refname: &str,
        ancestry: &HashSet<String>,
    ) -> anyhow::Result<bool> {
        if ancestry.contains(refname) {
            return Ok(true);
        }
        let direct = git.cherry_pick_right_only(base, refname)?;
        if is_cherry_pick_empty(&direct) {
            return Ok(true);
        }
        let squash = self.squash_commit(base, refname)?;
        let squash = git.cherry_pick_right_only(base, &format!("{}", squash))?;
        Ok(is_cherry_pick_empty(&squash))
    }
}

/// Everything we know about one branch after scanning.
#[derive(Debug)]
pub struct Entry {
    /// `refs/heads/<name>` for a local branch, `refs/remotes/<remote>/<name>` otherwise.
    pub refname: String,
    /// The kind of reference this entry describes.
    pub kind: Kind,
    /// Classification result.
    pub class: Class,
    /// Set when the branch is protected by a glob pattern.
    pub protected_by: Option<String>,
    /// Set when the branch is a base branch.
    pub base: bool,
    /// Set when the branch's upstream (local branch only) is a base branch.
    pub tracks_base: Option<String>,
    /// The worktree the branch is checked out in, when it is not the current one.
    pub worktree: Option<PathBuf>,
    /// Set when the branch is the HEAD of the worktree we run in.
    pub head: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Kind {
    Local {
        name: String,
        upstream: Option<RemoteRef>,
    },
    Remote {
        remote: String,
        name: String,
    },
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Class {
    /// Nothing can be said about this branch; it simply stays.
    Stays,
    /// Merged into a base branch.
    Merged,
    /// Stray: not merged, but the upstream is gone or already merged.
    Stray,
    /// Diverged from the other half of the tracking branch pair.
    Diverged(String),
}

impl Entry {
    /// The prefix used in the "Branches that will remain" listing.
    pub fn status_prefix(&self) -> String {
        match &self.kind {
            Kind::Local { upstream, .. } => match (&self.class, upstream) {
                (Class::Diverged(other), _) => format!("diverged with {}", other),
                (Class::Stray, _) => "stray".to_string(),
                (Class::Merged, None) => "merged non-tracking".to_string(),
                (Class::Merged, Some(_)) => "merged".to_string(),
                (Class::Stays, _) => String::new(),
            },
            Kind::Remote { .. } => match &self.class {
                Class::Diverged(other) => format!("diverged with {}", other),
                Class::Stray => "stray".to_string(),
                Class::Merged => {
                    if self.is_upstream() {
                        "merged".to_string()
                    } else {
                        "merged non-upstream".to_string()
                    }
                }
                Class::Stays => String::new(),
            },
        }
    }

    /// Is this entry the upstream of some local branch?
    pub fn is_upstream(&self) -> bool {
        matches!(self.kind, Kind::Remote { .. }) && !matches!(self.class, Class::Stays) && self.tracked
    }

    /// Set by the scanner when a local branch tracks this remote ref.
    pub tracked: bool,
}

/// Scan the repository: enumerate branches, classify them and collect the deletable ones.
pub struct Scan;

