//! `trim.*` configuration and the `--delete` range grammar.

use std::str::FromStr;

use anyhow::{anyhow, bail};
use git2::Config;

use crate::glob::Pattern;

/// One `<delete range>[:<remote name>]` token.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum DeleteRange {
    /// `merged-local`
    MergedLocal,
    /// `merged-remote:<remote>`
    MergedRemote(String),
    /// `stray`
    Stray,
    /// `diverged:<remote>`
    Diverged(String),
    /// `local`
    Local,
    /// `remote:<remote>`
    Remote(String),
}

impl DeleteRange {
    /// `merged` expands to `merged-local` plus `merged-remote:<remote>`.
    pub fn expand(spec: &str) -> anyhow::Result<Vec<DeleteRange>> {
        let mut out = Vec::new();
        for token in spec.split(',') {
            if token.is_empty() {
                continue;
            }
            let token = token.parse::<DeleteToken>()?;
            match token {
                DeleteToken::MergedLocal => out.push(DeleteRange::MergedLocal),
                DeleteToken::MergedRemote(remote) => out.push(DeleteRange::MergedRemote(remote)),
                DeleteToken::Stray => out.push(DeleteRange::Stray),
                DeleteToken::Diverged(remote) => out.push(DeleteRange::Diverged(remote)),
                DeleteToken::Local => out.push(DeleteRange::Local),
                DeleteToken::Remote(remote) => out.push(DeleteRange::Remote(remote)),
                DeleteToken::Merged(remote) => {
                    out.push(DeleteRange::MergedLocal);
                    out.push(DeleteRange::MergedRemote(remote));
                }
            }
        }
        Ok(out)
    }

    /// Does this range apply to `<remote name>` (or to every remote when it is `*`)?
    pub fn matches_remote(&self, remote: &str) -> bool {
        match self {
            DeleteRange::MergedRemote(r) | DeleteRange::Diverged(r) | DeleteRange::Remote(r) => {
                r == "*" || r == remote
            }
            _ => false,
        }
    }
}

/// A single token of the `--delete` option, before `merged` is expanded.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum DeleteToken {
    Merged(String),
    MergedLocal,
    MergedRemote(String),
    Stray,
    Diverged(String),
    Local,
    Remote(String),
}

const SCOPED: [&str; 4] = ["merged", "merged-remote", "diverged", "remote"];
const BARE: [&str; 3] = ["merged-local", "stray", "local"];

impl FromStr for DeleteToken {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let token = s.trim();
        match token.split_once(':') {
            None => {
                if BARE.contains(&token) {
                    Ok(match token {
                        "merged-local" => DeleteToken::MergedLocal,
                        "stray" => DeleteToken::Stray,
                        _ => DeleteToken::Local,
                    })
                } else {
                    Err(format!("Invalid delete range format `{}`", s))
                }
            }
            Some((name, scope)) => {
                if !SCOPED.contains(&name) {
                    return Err(format!("Invalid delete range format `{}`", s));
                }
