/// Everything read from the `trim.*` configuration.
#[derive(Debug, Default)]
pub struct TrimConfig {
    pub bases: Option<Vec<String>>,
    pub protected: Option<Vec<Pattern>>,
    pub update: bool,
    pub update_interval: Option<i64>,
    pub confirm: bool,
    pub detach: bool,
    pub delete: Option<Vec<DeleteRange>>,
}

fn split_commas(value: &str) -> Vec<String> {
    value.split(',').map(|s| s.to_string()).collect()
}

/// Parse a boolean the way libgit2 would, but never fail: unknown values mean `false`.
fn parse_bool(value: &str) -> bool {
    match value.to_ascii_lowercase().as_str() {
        "true" | "yes" | "on" => true,
        "false" | "no" | "off" | "" => false,
        _ => value.parse::<i64>().map(|n| n != 0).unwrap_or(false),
    }
