                eprintln!(" * `git trim --bases develop,master` to set temporarily.");
                bail!("No base branch is found!");
            }
            cfg.bases = Some(list);
        }
        Err(_) => {}
    }
    if let Ok(value) = config.get_string("trim.protected") {
        let patterns: Vec<Pattern> = split_commas(&value)
            .into_iter()
            .filter(|s| !s.is_empty())
            .map(Pattern::new)
            .collect();
        cfg.protected = Some(patterns);
    }
    if let Ok(value) = config.get_string("trim.update") {
        cfg.update = parse_bool(&value);
    }
    match config.get_i64("trim.updateInterval") {
        Ok(value) => cfg.update_interval = Some(value),
        Err(err) => {
            // A missing key is fine, anything else is a real configuration error.
            if !err.message().contains("was not found") {
                return Err(anyhow!("{}", err.message()));
            }
        }
    }
    if let Ok(value) = config.get_string("trim.confirm") {
        cfg.confirm = parse_bool(&value);
    }
    if let Ok(value) = config.get_string("trim.detach") {
        cfg.detach = parse_bool(&value);
    }
    match config.get_string("trim.delete") {
        Ok(value) => {
            if value.is_empty() {
                cfg.delete = Some(Vec::new());
            } else {
                cfg.delete = Some(DeleteRange::expand(&value)?);
            }
        }
        Err(_) => {}
    }
    Ok(cfg)
}
