//! A small glob matcher, enough for the `--protected` patterns.
//!
//! Supported syntax: `*` (any run of characters, including path separators), `?` (exactly one
//! character), character classes `[a-z]`/`[!abc]`/`[^abc]` and `\` escapes.  Brace alternation is
//! *not* supported, so `{a,b}` is matched literally.

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct Pattern {
    pattern: String,
