//! Remote repositories: listing, updating and asking for their HEAD.

use std::collections::BTreeMap;

use git2::Repository;

use crate::branch::parse_ls_remote_symref;
use crate::gitproc::Git;

/// A configured remote.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Remote {
    pub name: String,
}

/// List the remotes configured for `repo`, in the order `git` reports them.
pub fn list(repo: &Repository) -> anyhow::Result<Vec<Remote>> {
    let names = repo.remotes()?;
    let mut out = Vec::with_capacity(names.len());
    for i in 0..names.len() {
        if let Some(name) = names.get(i) {
            out.push(Remote { name: name.to_string() });
        }
    }
    Ok(out)
}

/// Fetch and prune every remote, unless we are only doing a dry run.
///
/// `git remote update --prune` handles all remotes at once, but `git-trim` announces each of them.
pub fn update(git: &Git, remotes: &[Remote], dry_run: bool) -> anyhow::Result<()> {
    if dry_run {
        return Ok(());
    }
    for remote in remotes {
        println!("Fetching {}", remote.name);
    }
    git.update_remotes()
}

/// Ask every remote for its HEAD symref.  Results are kept per remote name.
pub fn heads(git: &Git, remotes: &[Remote]) -> BTreeMap<String, anyhow::Result<String>> {
    let mut out = BTreeMap::new();
    for remote in remotes {
        let result = git
            .ls_remote_head(&remote.name)
            .and_then(|output| parse_ls_remote_symref(&output, &remote.name));
        out.insert(remote.name.clone(), result.map_err(anyhow::Error::from));
    }
    out
}
RSEOF
