//! The branch model: local branches, remote-tracking branches and their classification.
//!
//! Branch information is read from the repository through `git2`, while the "is it merged?"
//! question is delegated to `git`: first through `git branch --merged`, then through a
//! cherry-pick analysis, and finally through a synthetic squash-merge commit.

use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{anyhow, Context};
use git2::{ObjectType, Reference, Repository};

use crate::gitproc::Git;

/// A remote-tracking branch, e.g. `refs/remotes/origin/master`.
#[derive(Debug)]
pub struct RemoteTrackingBranch {
    pub refname: String,
}

/// A local branch, e.g. `refs/heads/master`.
#[derive(Debug)]
pub struct LocalBranch {
    pub refname: String,
}

/// Payload handed to the classifier for a single tracking branch.
#[derive(Debug)]
pub struct TrackingBranchClassificationRequest {
    pub base: RemoteTrackingBranch,
    pub local: LocalBranch,
    pub upstream: Option<RemoteTrackingBranch>,
}

/// A local branch discovered in the repository.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct LocalRef {
    pub name: String,
    pub refname: String,
}

/// A remote-tracking ref, e.g. `refs/remotes/origin/master`.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct RemoteRef {
    pub remote: String,
    pub name: String,
    pub refname: String,
}

impl RemoteRef {
    pub fn from_refname(refname: &str) -> Option<Self> {
        let rest = refname.strip_prefix("refs/remotes/")?;
        let (remote, name) = rest.split_once('/')?;
        Some(RemoteRef {
            remote: remote.to_string(),
            name: name.to_string(),
            refname: refname.to_string(),
        })
    }
}

impl LocalRef {
    pub fn from_refname(refname: &str) -> Option<Self> {
        let name = refname.strip_prefix("refs/heads/")?;
        Some(LocalRef {
            name: name.to_string(),
            refname: refname.to_string(),
        })
    }
}

/// Parse the output of `git branch --format %(refname) --merged <base>`.
pub fn parse_merged_locals(repo: &Repository, output: &str) -> anyhow::Result<Vec<LocalRef>> {
    let mut locals = Vec::new();
    for line in output.lines() {
        if !line.starts_with("refs/") {
            continue;
        }
        let refname = line;
        assert!(refname.starts_with("refs/heads/"));
        repo.find_reference(refname).with_context(|| {
            format!("could not look up reference `{}`", refname)
        })?;
        if let Some(local) = LocalRef::from_refname(refname) {
            locals.push(local);
        }
    }
    Ok(locals)
}

/// Parse the output of `git branch --format %(refname) --remote --merged <base>`.
pub fn parse_merged_remotes(repo: &Repository, output: &str) -> anyhow::Result<Vec<RemoteRef>> {
    let mut remotes = Vec::new();
    for line in output.lines() {
        let refname = line;
        assert!(refname.starts_with("refs/remotes/"));
        repo.find_reference(refname).with_context(|| {
            format!("could not look up reference `{}`", refname)
        })?;
        if let Some(remote) = RemoteRef::from_refname(refname) {
            remotes.push(remote);
        }
    }
    Ok(remotes)
}

/// Parse `git ls-remote --symref <remote> HEAD`, returning the symref the remote points at.
pub fn parse_ls_remote_symref(output: &str, remote: &str) -> anyhow::Result<String> {
    for line in output.lines() {
        let Some(rest) = line.strip_prefix("ref: ") else {
            continue;
        };
        let mut fields = rest.split('\t');
        let symref = fields.next().unwrap_or("");
        let name = fields.next().unwrap_or("");
        if name == "HEAD" {
            return Ok(symref.to_string());
        }
    }
    Err(anyhow!("HEAD not found on {}", remote))
}

/// A worktree checked out on a branch: `(path, branch refname)`.
pub type Worktree = (PathBuf, String);

/// Parse `git worktree list --porcelain`.
pub fn parse_worktrees(output: &str) -> Vec<Worktree> {
    let mut out = Vec::new();
    let mut current: Option<PathBuf> = None;
    let mut branch: Option<String> = None;
    for line in output.lines() {
        if let Some(path) = line.strip_prefix("worktree ") {
            if let (Some(path), Some(branch)) = (current.take(), branch.take()) {
                out.push((path, branch));
            }
            current = Some(PathBuf::from(path));
        } else if let Some(refname) = line.strip_prefix("branch ") {
            branch = Some(refname.to_string());
        }
    }
    if let (Some(path), Some(branch)) = (current.take(), branch.take()) {
        out.push((path, branch));
    }
    out
}

/// Empty output of the cherry-pick analysis means "merged".
fn cherry_pick_empty(output: &str) -> bool {
    !output.lines().any(|l| !l.trim().is_empty())
}

/// Detects squash merges by writing a synthetic commit into the object database.
pub struct SquashProbe<'a> {
    repo: &'a Repository,
    cache: HashMap<(git2::Oid, git2::Oid), git2::Oid>,
    marker: Phantom<()>,
}

/// Helper to keep `SquashProbe`'s `odb` field alive without exposing it in the public API.
struct Phantom<T>(T);

impl<'a> SquashProbe<'a> {
    pub fn new(repo: &'a Repository) -> anyhow::Result<Self> {
        let odb = repo.odb()?;
        Ok(SquashProbe {
            repo,
            cache: HashMap::new(),
            marker: Phantom(odb),
        })
    }

    /// Minutes between UTC and the local time zone, the way libgit2 computes it.
    fn local_offset_minutes(now: i64) -> i32 {
        let mut utc = libc::tm {
            tm_sec: 0,
            tm_min: 0,
            tm_hour: 0,
            tm_mday: 0,
            tm_mon: 0,
            tm_year: 0,
            tm_wday: 0,
            tm_yday: 0,
            tm_isdst: 0,
            tm_gmtoff: 0,
            tm_zone: std::ptr::null(),
        };
        unsafe {
            let t = now as libc::time_t;
            if libc::gmtime_r(&t, &mut utc).is_null() {
                return 0;
            }
            utc.tm_isdst = -1;
            let local = libc::mktime(&mut utc);
            (((local as i64) - now) / 60) as i32
        }
    }

    fn signature(now: i64) -> String {
        let offset = Self::local_offset_minutes(now);
        let (sign, offset) = if offset < 0 {
            ('-', -offset)
        } else {
            ('+', offset)
        };
        format!(
            "{}{:02}{:02}",
            sign,
            offset / 60,
            offset % 60
        )
    }

    /// Build the `git-trim: squash merge test` commit: the branch's tree on the merge base.
    fn squash_commit(&mut self, base: &str, refname: &str) -> anyhow::Result<git2::Oid> {
        let base_oid = self.repo.revparse_single(base)?.peel_to_commit()?.id();
        let ref_oid = self.repo.revparse_single(refname)?.peel_to_commit()?.id();
        let parent = self.repo.merge_base(base_oid, ref_oid)?;
        let tree = self.repo.find_commit(ref_oid)?.tree_id();

        if let Some(oid) = self.cache.get(&(parent, tree)) {
            return Ok(*oid);
        }

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let stamp = Self::signature(now);
        let name = "git-trim";
        let email = "git-trim@squash.merge.test.local";
        let data = format!(
            "tree {}\nparent {}\nauthor {} <{}> {} {}\ncommitter {} <{}> {} {}\n\ngit-trim: squash merge test",
            tree, parent, name, email, now, stamp, name, email, now, stamp,
        );
        let odb = self.repo.odb()?;
        let oid = odb.write(ObjectType::Commit, data.as_bytes())?;
        self.cache.insert((parent, tree), oid);
        Ok(oid)
    }

    /// Is `refname` merged into `base`?
    pub fn is_merged(
        &mut self,
        git: &Git,
        base: &str,
        refname: &str,
        ancestry: &HashSet<String>,
    ) -> anyhow::Result<bool> {
        if ancestry.contains(refname) {
            return Ok(true);
        }
        let direct = git.cherry_pick_right_only(base, refname)?;
        if cherry_pick_empty(&direct) {
            return Ok(true);
        }
        let squash = self.squash_commit(base, refname)?;
        let squash = git.cherry_pick_right_only(base, &format!("{}", squash))?;
        Ok(cherry_pick_empty(&squash))
    }
}

/// A base branch: where the merge analysis starts from.
#[derive(Clone, Debug)]
pub struct Base {
    /// The name as the user spelled it, echoed back in annotations.
    pub spec: String,
    /// The remote-tracking ref used for the merge analysis.
    pub refname: String,
    /// The local branch of the base, when the base is one.
    pub local: Option<String>,
}

/// One branch after scanning.
#[derive(Debug)]
pub struct Entry {
    /// `refs/heads/<name>` for a local branch, `refs/remotes/<remote>/<name>` otherwise.
    pub refname: String,
    /// The kind of reference this entry describes.
    pub kind: Kind,
    /// Classification result.
    pub class: Class,
    /// For remote refs: is some local branch tracking this one?
    pub tracked: bool,
    /// Is this entry one of the base branches?
    pub base: bool,
    /// The base spec of the base branch this entry tracks, for local branches.
    pub tracks_base: Option<String>,
    /// The pattern protecting this branch, when it is protected.
    pub protected_by: Option<String>,
    /// The worktree this branch is checked out in, when it is not the current one.
    pub worktree: Option<PathBuf>,
    /// Is this branch the HEAD of the worktree we run in?
    pub head: bool,
}

/// What kind of reference an [`Entry`] describes.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Kind {
    Local {
        name: String,
        upstream: Option<RemoteRef>,
    },
    Remote {
        remote: String,
        name: String,
    },
}

/// Classification of a branch.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Class {
    /// Nothing can be said about this branch, it simply stays.
    Stays,
    /// Merged into a base branch.
    Merged,
    /// Not merged, but its upstream is gone or already merged.
    Stray,
    /// Diverged from the other half of the tracking branch pair.
    Diverged(String),
}

impl Entry {
    /// The prefix used in the "Branches that will remain" listing.
    pub fn status_prefix(&self) -> String {
        match (&self.class, &self.kind) {
            (Class::Diverged(other), _) => format!("diverged with {}", other),
            (Class::Stray, _) => "stray".to_string(),
            (Class::Merged, Kind::Local { upstream: None, .. }) => "merged non-tracking".to_string(),
            (Class::Merged, Kind::Remote { .. }) if !self.tracked => {
                "merged non-upstream".to_string()
            }
            (Class::Merged, _) => "merged".to_string(),
            (Class::Stays, _) => String::new(),
        }
    }

    /// The local branch name, when this entry describes one.
    pub fn local_name(&self) -> Option<&str> {
        match &self.kind {
            Kind::Local { name, .. } => Some(name),
            _ => None,
        }
    }

    /// The remote name, when this entry describes a remote-tracking ref.
    pub fn remote_name(&self) -> Option<&str> {
        match &self.kind {
            Kind::Remote { remote, .. } => Some(remote),
            _ => None,
        }
    }
}

/// Enumerate the references of `repo`, split into local branches and remote-tracking refs.
pub fn list_refs(repo: &Repository) -> anyhow::Result<(Vec<LocalRef>, Vec<RemoteRef>)> {
    let mut locals = Vec::new();
    let mut remotes = Vec::new();
    let references = repo.references()?;
    for reference in references {
        let reference = reference?;
        let kind = reference.kind();
        let Some(name) = reference.name() else {
            continue;
        };
        match kind {
            Some(git2::ReferenceType::Direct) => {
                if let Some(local) = LocalRef::from_refname(name) {
                    locals.push(local);
                } else if let Some(remote) = RemoteRef::from_refname(name) {
                    if remote.name != "HEAD" {
                        remotes.push(remote);
                    }
                }
            }
            _ => {}
        }
    }
    locals.sort();
    remotes.sort();
    Ok((locals, remotes))
}

/// Read the remote-tracking ref a local branch is configured to track.
pub fn upstream_refname(
    repo: &Repository,
    local: &LocalRef,
    refs: &HashSet<String>,
) -> anyhow::Result<Option<RemoteRef>> {
    let config = repo.config()?;
    let remote = match config.get_string(&format!("branch.{}.remote", local.name)) {
        Ok(value) => value,
        Err(_) => return Ok(None),
    };
    let merge = match config.get_string(&format!("branch.{}.merge", local.name)) {
        Ok(value) => value,
        Err(_) => return Ok(None),
    };
    let Some(name) = merge.strip_prefix("refs/heads/") else {
        return Ok(None);
    };
    let refname = format!("refs/remotes/{}/{}/", remote, name);
    let refname = refname.trim_end_matches('/').to_string();
    if !refs.contains(&refname) {
        return Ok(None);
    }
    Ok(Some(RemoteRef {
        remote,
        name: name.to_string(),
        refname,
    }))
}

/// Collect every reference name present in the repository.
pub fn all_refnames(repo: &Repository) -> anyhow::Result<HashSet<String>> {
    let mut out = HashSet::new();
    let references = repo.references()?;
    for reference in references {
        let reference = reference?;
        if let Some(name) = reference.name() {
            out.insert(name.to_string());
        }
    }
    Ok(out)
}

/// The reference behind `refname`, resolving symbolic references like `refs/remotes/*/HEAD`.
pub fn resolve(repo: &Repository, refname: &str) -> anyhow::Result<Reference<'_>> {
    repo.find_reference(refname)
}

