}

/// A local branch discovered in the repository.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct LocalRef {
    pub name: String,
    pub refname: String,
}

/// A remote-tracking ref, e.g. `refs/remotes/origin/master`.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct RemoteRef {
    pub remote: String,
    pub name: String,
    pub refname: String,
}

impl RemoteRef {
    pub fn from_refname(refname: &str) -> Option<Self> {
        let rest = refname.strip_prefix("refs/remotes/")?;
        let (remote, name) = rest.split_once('/')?;
        Some(RemoteRef {
            remote: remote.to_string(),
            name: name.to_string(),
            refname: refname.to_string(),
        })
    }
}

impl LocalRef {
    pub fn from_refname(refname: &str) -> Option<Self> {
        let name = refname.strip_prefix("refs/heads/")?;
        Some(LocalRef {
            name: name.to_string(),
            refname: refname.to_string(),
        })
    }
}

/// Parse the output of `git branch --format %(refname) --merged <base>`.
pub fn parse_merged_locals(repo: &Repository, output: &str) -> anyhow::Result<Vec<LocalRef>> {
    let mut locals = Vec::new();
    for line in output.lines() {
        if !line.starts_with("refs/") {
            continue;
        }
        let refname = line;
        assert!(refname.starts_with("refs/heads/"));
        repo.find_reference(refname).with_context(|| {
            format!("could not look up reference `{}`", refname)
        })?;
        if let Some(local) = LocalRef::from_refname(refname) {
            locals.push(local);
        }
    }
    Ok(locals)
}

/// Parse the output of `git branch --format %(refname) --remote --merged <base>`.
pub fn parse_merged_remotes(repo: &Repository, output: &str) -> anyhow::Result<Vec<RemoteRef>> {
    let mut remotes = Vec::new();
    for line in output.lines() {
        let refname = line;
        assert!(refname.starts_with("refs/remotes/"));
        repo.find_reference(refname).with_context(|| {
            format!("could not look up reference `{}`", refname)
        })?;
        if let Some(remote) = RemoteRef::from_refname(refname) {
            remotes.push(remote);
        }
    }
    Ok(remotes)
}

/// Parse `git ls-remote --symref <remote> HEAD`, returning the symref the remote points at.
pub fn parse_ls_remote_symref(output: &str, remote: &str) -> anyhow::Result<String> {
    for line in output.lines() {
        let Some(rest) = line.strip_prefix("ref: ") else {
            continue;
        };
        let mut fields = rest.split('\t');
        let symref = fields.next().unwrap_or("");
        let name = fields.next().unwrap_or("");
        if name == "HEAD" {
            return Ok(symref.to_string());
        }
    }
    Err(anyhow!("HEAD not found on {}", remote))
}

/// A worktree checked out on a branch: `(path, branch refname)`.
pub type Worktree = (PathBuf, String);

/// Parse `git worktree list --porcelain`.
pub fn parse_worktrees(output: &str) -> Vec<Worktree> {
    let mut out = Vec::new();
    let mut current: Option<PathBuf> = None;
    let mut branch: Option<String> = None;
    for line in output.lines() {
        if let Some(path) = line.strip_prefix("worktree ") {
            if let (Some(path), Some(branch)) = (current.take(), branch.take()) {
                out.push((path, branch));
            }
            current = Some(PathBuf::from(path));
        } else if let Some(refname) = line.strip_prefix("branch ") {
            branch = Some(refname.to_string());
        }
    }
    if let (Some(path), Some(branch)) = (current.take(), branch.take()) {
        out.push((path, branch));
    }
    out
}

