    pub refname: String,
}

/// A remote-tracking ref, e.g. `refs/remotes/origin/master`.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct RemoteRef {
    pub remote: String,
    pub name: String,
    pub refname: String,
}

impl RemoteRef {
    pub fn from_refname(refname: &str) -> Option<Self> {
        let rest = refname.strip_prefix("refs/remotes/")?;
        let (remote, name) = rest.split_once('/')?;
        Some(RemoteRef {
            remote: remote.to_string(),
            name: name.to_string(),
            refname: refname.to_string(),
        })
    }
}

impl LocalRef {
    pub fn from_refname(refname: &str) -> Option<Self> {
        let name = refname.strip_prefix("refs/heads/")?;
        Some(LocalRef {
            name: name.to_string(),
            refname: refname.to_string(),
        })
    }
}

/// Parse the output of `git branch --format %(refname) --merged <base>`.
pub fn parse_merged_locals(repo: &Repository, output: &str) -> anyhow::Result<Vec<LocalRef>> {
    let mut locals = Vec::new();
    for line in output.lines() {
        if !line.starts_with("refs/") {
            continue;
        }
        let refname = line;
        assert!(refname.starts_with("refs/heads/"));
        repo.find_reference(refname).with_context(|| {
            format!("could not look up reference `{}`", refname)
        })?;
        if let Some(local) = LocalRef::from_refname(refname) {
            locals.push(local);
        }
    }
    Ok(locals)
}

/// Parse the output of `git branch --format %(refname) --remote --merged <base>`.
pub fn parse_merged_remotes(repo: &Repository, output: &str) -> anyhow::Result<Vec<RemoteRef>> {
    let mut remotes = Vec::new();
    for line in output.lines() {
        let refname = line;
        assert!(refname.starts_with("refs/remotes/"));
        repo.find_reference(refname).with_context(|| {
            format!("could not look up reference `{}`", refname)
        })?;
        if let Some(remote) = RemoteRef::from_refname(refname) {
            remotes.push(remote);
        }
    }
    Ok(remotes)
}

/// Parse `git ls-remote --symref <remote> HEAD`, returning the symref the remote points at.
pub fn parse_ls_remote_symref(output: &str, remote: &str) -> anyhow::Result<String> {
    for line in output.lines() {
        let Some(rest) = line.strip_prefix("ref: ") else {
            continue;
        };
        let mut fields = rest.split('\t');
        let symref = fields.next().unwrap_or("");
        let name = fields.next().unwrap_or("");
        if name == "HEAD" {
            return Ok(symref.to_string());
        }
    }
    Err(anyhow!("HEAD not found on {}", remote))
}

/// A worktree checked out on a branch: `(path, branch refname)`.
pub type Worktree = (PathBuf, String);

/// Parse `git worktree list --porcelain`.
pub fn parse_worktrees(output: &str) -> Vec<Worktree> {
    let mut out = Vec::new();
    let mut current: Option<PathBuf> = None;
    let mut branch: Option<String> = None;
    for line in output.lines() {
        if let Some(path) = line.strip_prefix("worktree ") {
            if let (Some(path), Some(branch)) = (current.take(), branch.take()) {
                out.push((path, branch));
            }
            current = Some(PathBuf::from(path));
        } else if let Some(refname) = line.strip_prefix("branch ") {
            branch = Some(refname.to_string());
        }
    }
    if let (Some(path), Some(branch)) = (current.take(), branch.take()) {
        out.push((path, branch));
    }
    out
}

/// Empty output of the cherry-pick analysis means "merged".
fn cherry_pick_empty(output: &str) -> bool {
    !output.lines().any(|l| !l.trim().is_empty())
}

/// Detects squash merges by writing a synthetic commit into the object database.
pub struct SquashProbe<'a> {
    repo: &'a Repository,
    cache: HashMap<(git2::Oid, git2::Oid), git2::Oid>,
    marker: Phantom<()>,
}

/// Helper to keep `SquashProbe`'s `odb` field alive without exposing it in the public API.
struct Phantom<T>(T);

impl<'a> SquashProbe<'a> {
    pub fn new(repo: &'a Repository) -> anyhow::Result<Self> {
        let odb = repo.odb()?;
        Ok(SquashProbe {
            repo,
            cache: HashMap::new(),
            marker: Phantom(odb),
        })
    }

    /// Minutes between UTC and the local time zone, the way libgit2 computes it.
    fn local_offset_minutes(now: i64) -> i32 {
        let mut utc = libc::tm {
            tm_sec: 0,
            tm_min: 0,
            tm_hour: 0,
            tm_mday: 0,
            tm_mon: 0,
            tm_year: 0,
            tm_wday: 0,
            tm_yday: 0,
            tm_isdst: 0,
            tm_gmtoff: 0,
            tm_zone: std::ptr::null(),
        };
        unsafe {
            let t = now as libc::time_t;
            if libc::gmtime_r(&t, &mut utc).is_null() {
                return 0;
            }
            utc.tm_isdst = -1;
            let local = libc::mktime(&mut utc);
            (((local as i64) - now) / 60) as i32
        }
    }

    fn signature(now: i64) -> String {
        let offset = Self::local_offset_minutes(now);
        let (sign, offset) = if offset < 0 {
            ('-', -offset)
        } else {
            ('+', offset)
        };
        format!(
            "{}{:02}{:02}",
            sign,
            offset / 60,
            offset % 60
        )
    }

    /// Build the `git-trim: squash merge test` commit: the branch's tree on the merge base.
    fn squash_commit(&mut self, base: &str, refname: &str) -> anyhow::Result<git2::Oid> {
        let base_oid = self.repo.revparse_single(base)?.peel_to_commit()?.id();
        let ref_oid = self.repo.revparse_single(refname)?.peel_to_commit()?.id();
        let parent = self.repo.merge_base(base_oid, ref_oid)?;
        let tree = self.repo.find_commit(ref_oid)?.tree_id();

        if let Some(oid) = self.cache.get(&(parent, tree)) {
            return Ok(*oid);
        }

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let stamp = Self::signature(now);
        let name = "git-trim";
        let email = "git-trim@squash.merge.test.local";
        let data = format!(
            "tree {}\nparent {}\nauthor {} <{}> {} {}\ncommitter {} <{}> {} {}\n\ngit-trim: squash merge test",
            tree, parent, name, email, now, stamp, name, email, now, stamp,
        );
        let odb = self.repo.odb()?;
        let oid = odb.write(ObjectType::Commit, data.as_bytes())?;
        self.cache.insert((parent, tree), oid);
        Ok(oid)
    }

    /// Is `refname` merged into `base`?
    pub fn is_merged(
        &mut self,
        git: &Git,
        base: &str,
        refname: &str,
        ancestry: &HashSet<String>,
    ) -> anyhow::Result<bool> {
        if ancestry.contains(refname) {
            return Ok(true);
        }
        let direct = git.cherry_pick_right_only(base, refname)?;
        if cherry_pick_empty(&direct) {
            return Ok(true);
        }
        let squash = self.squash_commit(base, refname)?;
        let squash = git.cherry_pick_right_only(base, &format!("{}", squash))?;
        Ok(cherry_pick_empty(&squash))
    }
}

/// A base branch: where the merge analysis starts from.
#[derive(Clone, Debug)]
pub struct Base {
    /// The name as the user spelled it, echoed back in annotations.
    pub spec: String,
    /// The remote-tracking ref used for the merge analysis.
    pub refname: String,
    /// The local branch of the base, when the base is one.
    pub local: Option<String>,
}

/// One branch after scanning.
#[derive(Debug)]
pub struct Entry {
    /// `refs/heads/<name>` for a local branch, `refs/remotes/<remote>/<name>` otherwise.
    pub refname: String,
    /// The kind of reference this entry describes.
    pub kind: Kind,
    /// Classification result.
    pub class: Class,
    /// For remote refs: is some local branch tracking this one?
    pub tracked: bool,
    /// Is this entry one of the base branches?
    pub base: bool,
    /// The base spec of the base branch this entry tracks, for local branches.
    pub tracks_base: Option<String>,
    /// The pattern protecting this branch, when it is protected.
    pub protected_by: Option<String>,
    /// The worktree this branch is checked out in, when it is not the current one.
    pub worktree: Option<PathBuf>,
    /// Is this branch the HEAD of the worktree we run in?
    pub head: bool,
}

/// What kind of reference an [`Entry`] describes.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Kind {
    Local {
        name: String,
        upstream: Option<RemoteRef>,
    },
    Remote {
        remote: String,
        name: String,
    },
}

/// Classification of a branch.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Class {
    /// Nothing can be said about this branch, it simply stays.
    Stays,
    /// Merged into a base branch.
    Merged,
    /// Not merged, but its upstream is gone or already merged.
    Stray,
    /// Diverged from the other half of the tracking branch pair.
    Diverged(String),
}

impl Entry {
    /// The prefix used in the "Branches that will remain" listing.
    pub fn status_prefix(&self) -> String {
        match (&self.class, &self.kind) {
            (Class::Diverged(other), _) => format!("diverged with {}", other),
            (Class::Stray, _) => "stray".to_string(),
            (Class::Merged, Kind::Local { upstream: None, .. }) => "merged non-tracking".to_string(),
            (Class::Merged, Kind::Remote { .. }) if !self.tracked => {
                "merged non-upstream".to_string()
            }
            (Class::Merged, _) => "merged".to_string(),
            (Class::Stays, _) => String::new(),
        }
    }

    /// The local branch name, when this entry describes one.
    pub fn local_name(&self) -> Option<&str> {
        match &self.kind {
            Kind::Local { name, .. } => Some(name),
            _ => None,
        }
    }

    /// The remote name, when this entry describes a remote-tracking ref.
    pub fn remote_name(&self) -> Option<&str> {
        match &self.kind {
            Kind::Remote { remote, .. } => Some(remote),
            _ => None,
        }
    }
}

/// Enumerate the references of `repo`, split into local branches and remote-tracking refs.
pub fn list_refs(repo: &Repository) -> anyhow::Result<(Vec<LocalRef>, Vec<RemoteRef>)> {
    let mut locals = Vec::new();
    let mut remotes = Vec::new();
    let references = repo.references()?;
    for reference in references {
        let reference = reference?;
        let kind = reference.kind();
        let Some(name) = reference.name() else {
            continue;
        };
        match kind {
            Some(git2::ReferenceType::Direct) => {
                if let Some(local) = LocalRef::from_refname(name) {
                    locals.push(local);
                } else if let Some(remote) = RemoteRef::from_refname(name) {
                    if remote.name != "HEAD" {
                        remotes.push(remote);
                    }
                }
            }
            _ => {}
        }
    }
    locals.sort();
    remotes.sort();
    Ok((locals, remotes))
}

/// Read the remote-tracking ref a local branch is configured to track.
pub fn upstream_refname(
    repo: &Repository,
    local: &LocalRef,
    refs: &HashSet<String>,
) -> anyhow::Result<Option<RemoteRef>> {
    let config = repo.config()?;
    let remote = match config.get_string(&format!("branch.{}.remote", local.name)) {
        Ok(value) => value,
        Err(_) => return Ok(None),
    };
    let merge = match config.get_string(&format!("branch.{}.merge", local.name)) {
        Ok(value) => value,
        Err(_) => return Ok(None),
    };
    let Some(name) = merge.strip_prefix("refs/heads/") else {
        return Ok(None);
    };
    let refname = format!("refs/remotes/{}/{}/", remote, name);
    let refname = refname.trim_end_matches('/').to_string();
    if !refs.contains(&refname) {
        return Ok(None);
    }
    Ok(Some(RemoteRef {
        remote,
        name: name.to_string(),
        refname,
    }))
}

/// Collect every reference name present in the repository.
pub fn all_refnames(repo: &Repository) -> anyhow::Result<HashSet<String>> {
    let mut out = HashSet::new();
    let references = repo.references()?;
    for reference in references {
        let reference = reference?;
        if let Some(name) = reference.name() {
            out.insert(name.to_string());
        }
    }
    Ok(out)
}

/// The reference behind `refname`, resolving symbolic references like `refs/remotes/*/HEAD`.
pub fn resolve(repo: &Repository, refname: &str) -> anyhow::Result<Reference<'_>> {
    repo.find_reference(refname)
}

RSEOF
echo ok"}

{"command": "cat <<'RSEOF' > /workspace/src/scan.rs
//! Scanning a repository: enumerating branches, classifying them against the base branches and
//! figuring out which ones `git-trim` would delete.

use std::collections::{BTreeMap, HashMap, HashSet};
use std::path::Path;

use anyhow::Context;
use git2::Repository;

use crate::branch::{
    parse_merged_locals, parse_merged_remotes, parse_worktrees, Base, Class, Entry, Kind, LocalRef,
    RemoteRef, SquashProbe,
};
use crate::config::TrimConfig;
use crate::glob::Pattern;
use crate::gitproc::Git;

/// Everything we learned about the repository in one pass.
pub struct Scan {
    /// Branch entries, in the order the repository reports its references.
    pub entries: Vec<Entry>,
    /// The base branches the analysis used.
    pub bases: Vec<Base>,
    /// Remote HEAD symrefs as the remote reports them.
    pub remote_heads: BTreeMap<String, anyhow::Result<String>>,
}

/// Resolve `--bases` / `trim.bases` / `refs/remotes/*/HEAD` into the list of base branches.
pub fn bases(
    repo: &Repository,
    locals: &[LocalRef],
    remotes: &[RemoteRef],
    remote_names: &[String],
    explicit: Option<&[String]>,
    default_bases: bool,
) -> anyhow::Result<Vec<Base>> {
    let local_by_name: HashMap<&str, &LocalRef> =
        locals.iter().map(|l| (l.name.as_str(), l)).collect();
    let remote_refs: HashSet<&str> = remotes.iter().map(|r| r.refname.as_str()).collect();
    let mut out: Vec<Base> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();

    if let Some(specs) = explicit {
        for spec in specs {
            let reference = match repo.resolve_reference_from_short_name(spec) {
                Ok(reference) => reference,
                Err(err) if err.code() == git2::ErrorCode::NotFound => continue,
                Err(err) => return Err(anyhow::Error::new(err)),
            };
            let name = reference.name()?.to_string();
            let base = if let Some(local) = name.strip_prefix("refs/heads/") {
                let Some(local) = local_by_name.get(local) else {
                    continue;
                };
                let upstream = crate::branch::upstream_refname(repo, local, &refnames)?;
                let Some(upstream) = upstream else {
                    continue;
                };
                Base {
                    spec: spec.to_string(),
                    refname: upstream.refname.clone(),
                    local: Some(local.refname.clone()),
                }
            } else if name.starts_with("refs/remotes/") {
                Base {
                    spec: spec.to_string(),
                    refname: name.clone(),
                    local: None,
                }
            } else {
                continue;
            };
            if seen.insert(base.refname.clone()) {
                out.push(base);
            }
        }
        return Ok(out);
    }

    for remote in remote_names {
        let head_refname = format!("refs/remotes/{}/HEAD", remote);
        let reference = match repo.find_reference(&head_refname) {
            Ok(reference) => reference,
            Err(_) => continue,
        };
        let target = match reference.symbolic_target() {
            Ok(Some(target)) => target.to_string(),
            _ => continue,
        };
        let prefix = format!("refs/remotes/{}/", remote);
        let Some(branch) = target.strip_prefix(&prefix) else {
            continue;
        };
        let refname = match local_by_name.get(branch) {
            Some(local) => match crate::branch::upstream_refname(repo, local, &refnames)? {
                Some(upstream) => upstream.refname,
                None => target.clone(),
            },
            None => target.clone(),
        };
        if !seen.insert(branch.to_string()) {
            continue;
        }
        out.push(Base {
            spec: branch.to_string(),
            refname,
            local: local_by_name
                .get(branch)
                .map(|l| l.refname.clone()),
        });
    }
    let _ = default_bases;
    Ok(out)
}

/// Run the whole scan.
pub fn run(
    repo: &Repository,
    git: &Git,
    config: &TrimConfig,
    explicit_bases: Option<&[String]>,
    protected: &[Pattern],
    dry_run: bool,
    remote_names: &[String],
    remote_heads: BTreeMap<String, anyhow::Result<String>>,
) -> anyhow::Result<Scan> {
    let (locals, remotes) = crate::branch::list_refs(repo)?;
    let refnames = crate::branch::all_refnames(repo)?;
    let bases = bases(repo, &locals, &remotes, remote_names, explicit_bases, true)?;

    let mut ancestry_locals: HashMap<String, HashSet<String>> = HashMap::new();
    let mut ancestry_remotes: HashMap<String, HashSet<String>> = HashMap::new();
    for base in &bases {
        let output = git
            .merged_refs(&base.refname, false)
            .map_err(anyhow::Error::from)?;
        let list = parse_merged_locals(repo, &output)?;
        ancestry_locals
            .entry(base.refname.clone())
            .or_default()
            .extend(list.into_iter().map(|l| l.refname));
        let output = git
            .merged_refs(&base.refname, true)
            .map_err(anyhow::Error::from)?;
        let list = parse_merged_remotes(repo, &output)?;
        ancestry_remotes
            .entry(base.refname.clone())
            .or_default()
            .extend(list.into_iter().map(|r| r.refname));
    }

    let mut probe = SquashProbe::new(repo)?;
    let is_merged_local = |probe: &mut SquashProbe, refname: &str| -> anyhow::Result<bool> {
        for base in &bases {
            let set = ancestry_locals.get(&base.refname).unwrap();
            if probe.is_merged(git, &base.refname, refname, set)? {
                return Ok(true);
            }
        }
        Ok(false)
    };
    let is_merged_remote = |probe: &mut SquashProbe, refname: &str| -> anyhow::Result<bool> {
        for base in &bases {
            let set = ancestry_remotes.get(&base.refname).unwrap();
            if probe.is_merged(git, &base.refname, refname, set)? {
                return Ok(true);
            }
        }
        Ok(false)
    };

    // Worktrees: which branch is checked out where, and which one is ours.
    let worktrees = parse_worktrees(
        &git.worktree_list().map_err(anyhow::Error::from)?,
    );
    let current = repo.workdir().map(Path::new);
    let mut worktree_of: HashMap<&str, &Path> = HashMap::new();
    let mut head_branch: Option<String> = None;
    for (path, refname) in &worktrees {
        let is_current = current.map(|c| c == path.as_path()).unwrap_or(false);
        if is_current {
            head_branch = Some(refname.clone());
        } else {
            worktree_of.insert(refname.as_str(), path.as_path());
        }
    }

    // Classify local branches first, keeping the results around for their upstreams.
    let mut local_class: HashMap<&str, Class> = HashMap::new();
    for local in &locals {
        let class = match crate::branch::upstream_refname(repo, local, &refnames)? {
            Some(upstream) => {
                let merged_local = is_merged_local(&mut probe, &local.refname)?;
                let merged_upstream = is_merged_remote(&mut probe, &upstream.refname)?;
                if merged_local {
                    if merged_upstream {
                        Class::Merged
                    } else {
                        Class::Diverged(upstream.refname.clone())
                    }
                } else if merged_upstream {
                    Class::Stray
                } else {
                    Class::Stays
                }
            }
            None => {
                if is_merged_local(&mut probe, &local.refname)? {
                    Class::Merged
                } else {
                    Class::Stays
                }
            }
        };
        local_class.insert(local.refname.as_str(), class);
    }

    let upstream_of: HashMap<&str, Vec<&str>> = {
        let mut map: HashMap<&str, Vec<&str>> = HashMap::new();
        for local in &locals {
            if let Some(upstream) = crate::branch::upstream_refname(repo, local, &refnames)? {
                map.entry(upstream.refname.as_str())
                    .or_default()
                    .push(local.refname.as_str());
            }
        }
        map
    };

    let mut entries = Vec::new();
    for local in &locals {
        let upstream = crate::branch::upstream_refname(repo, local, &refnames)?;
        let class = local_class.get(local.refname.as_str()).cloned().unwrap();
        let base = bases
            .iter()
            .any(|b| Some(&b.refname) == upstream.as_ref().map(|u| &u.refname) || b.local.as_deref() == Some(local.refname.as_str()));
        let tracks_base = bases
            .iter()
            .find(|b| Some(&b.refname) == upstream.as_ref().map(|u| &u.refname))
            .map(|b| b.spec.clone());
        let worktree = worktree_of.get(local.refname.as_str()).map(|p| (*p).to_path_buf());
        let head = head_branch.as_deref() == Some(local.refname.as_str());
        entries.push(Entry {
            refname: local.refname.clone(),
            kind: Kind::Local {
                name: local.name.clone(),
                upstream: upstream.clone(),
            },
            class,
            tracked: false,
            base,
            tracks_base,
            protected_by: None,
            worktree,
            head,
        });
    }
    for remote in &remotes {
        let tracked = upstream_of.contains_key(remote.refname.as_str());
        let class = if tracked {
            let local_refname = upstream_of[remote.refname.as_str()][0];
            match local_class.get(local_refname) {
                Some(Class::Diverged(other)) if other == &remote.refname => Class::Diverged(local_refname.to_string()),
                Some(Class::Stray) => Class::Stray,
                _ => {
                    if is_merged_remote(&mut probe, &remote.refname)? {
                        Class::Merged
                    } else {
                        Class::Stays
                    }
                }
            }
        } else if is_merged_remote(&mut probe, &remote.refname)? {
            Class::Merged
        } else {
            Class::Stays
        };
        let base = bases.iter().any(|b| b.refname == remote.refname);
        entries.push(Entry {
            refname: remote.refname.clone(),
            kind: Kind::Remote {
                remote: remote.remote.clone(),
                name: remote.name.clone(),
            },
            class,
            tracked,
            base,
            tracks_base: None,
            protected_by: None,
            worktree: None,
            head: false,
        });
    }

    for entry in &mut entries {
        entry.protected_by = protect(protected, entry);
    }

    Ok(Scan {
        entries,
        bases,
        remote_heads,
    })
}

/// Names a branch is known by, in the order the protection check considers them.
fn names(entry: &Entry) -> Vec<String> {
    match &entry.kind {
        Kind::Local { name, .. } => vec![name.clone(), entry.refname.clone()],
        Kind::Remote { remote, name } => {
            vec![format!("{}/{}", remote, name), entry.refname.clone()]
        }
    }
}

fn protect(patterns: &[Pattern], entry: &Entry) -> Option<String> {
    if entry.base {
        return None;
    }
    for name in names(entry) {
        for pattern in patterns {
            if pattern.is_match(&name) {
                return Some(pattern.as_str().to_string());
            }
        }
    }
    None
}
