use crate::config::TrimConfig;
use crate::glob::Pattern;
use crate::gitproc::Git;

/// Everything we learned about the repository in one pass.
pub struct Scan {
    /// Branch entries, in the order the repository reports its references.
    pub entries: Vec<Entry>,
    /// The base branches the analysis used.
    pub bases: Vec<Base>,
    /// Remote HEAD symrefs as the remote reports them.
    pub remote_heads: BTreeMap<String, anyhow::Result<String>>,
}

/// Resolve `--bases` / `trim.bases` / `refs/remotes/*/HEAD` into the list of base branches.
pub fn bases(
    repo: &Repository,
    locals: &[LocalRef],
    remotes: &[RemoteRef],
    remote_names: &[String],
    explicit: Option<&[String]>,
    default_bases: bool,
) -> anyhow::Result<Vec<Base>> {
    let local_by_name: HashMap<&str, &LocalRef> =
        locals.iter().map(|l| (l.name.as_str(), l)).collect();
    let remote_refs: HashSet<&str> = remotes.iter().map(|r| r.refname.as_str()).collect();
    let mut out: Vec<Base> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();

    if let Some(specs) = explicit {
        for spec in specs {
            let reference = match repo.resolve_reference_from_short_name(spec) {
                Ok(reference) => reference,
                Err(err) if err.code() == git2::ErrorCode::NotFound => continue,
                Err(err) => return Err(anyhow::Error::new(err)),
            };
            let name = reference.name()?.to_string();
            let base = if let Some(local) = name.strip_prefix("refs/heads/") {
                let Some(local) = local_by_name.get(local) else {
                    continue;
                };
                let upstream = crate::branch::upstream_refname(repo, local, &refnames)?;
                let Some(upstream) = upstream else {
                    continue;
                };
                Base {
                    spec: spec.to_string(),
                    refname: upstream.refname.clone(),
                    local: Some(local.refname.clone()),
                }
            } else if name.starts_with("refs/remotes/") {
                Base {
                    spec: spec.to_string(),
                    refname: name.clone(),
                    local: None,
                }
            } else {
                continue;
            };
            if seen.insert(base.refname.clone()) {
                out.push(base);
            }
        }
        return Ok(out);
    }

    for remote in remote_names {
        let head_refname = format!("refs/remotes/{}/HEAD", remote);
        let reference = match repo.find_reference(&head_refname) {
            Ok(reference) => reference,
            Err(_) => continue,
        };
        let target = match reference.symbolic_target() {
            Ok(Some(target)) => target.to_string(),
            _ => continue,
        };
        let prefix = format!("refs/remotes/{}/", remote);
        let Some(branch) = target.strip_prefix(&prefix) else {
            continue;
        };
        let refname = match local_by_name.get(branch) {
            Some(local) => match crate::branch::upstream_refname(repo, local, &refnames)? {
                Some(upstream) => upstream.refname,
                None => target.clone(),
            },
            None => target.clone(),
        };
        if !seen.insert(branch.to_string()) {
            continue;
        }
        out.push(Base {
            spec: branch.to_string(),
            refname,
            local: local_by_name
                .get(branch)
                .map(|l| l.refname.clone()),
        });
    }
    let _ = default_bases;
    Ok(out)
}

/// Run the whole scan.
pub fn run(
    repo: &Repository,
    git: &Git,
    config: &TrimConfig,
    explicit_bases: Option<&[String]>,
    protected: &[Pattern],
    dry_run: bool,
    remote_names: &[String],
    remote_heads: BTreeMap<String, anyhow::Result<String>>,
) -> anyhow::Result<Scan> {
    let (locals, remotes) = crate::branch::list_refs(repo)?;
    let refnames = crate::branch::all_refnames(repo)?;
    let bases = bases(repo, &locals, &remotes, remote_names, explicit_bases, true)?;

    let mut ancestry_locals: HashMap<String, HashSet<String>> = HashMap::new();
    let mut ancestry_remotes: HashMap<String, HashSet<String>> = HashMap::new();
    for base in &bases {
        let output = git
            .merged_refs(&base.refname, false)
            .map_err(anyhow::Error::from)?;
        let list = parse_merged_locals(repo, &output)?;
        ancestry_locals
            .entry(base.refname.clone())
            .or_default()
            .extend(list.into_iter().map(|l| l.refname));
        let output = git
            .merged_refs(&base.refname, true)
            .map_err(anyhow::Error::from)?;
        let list = parse_merged_remotes(repo, &output)?;
        ancestry_remotes
            .entry(base.refname.clone())
            .or_default()
            .extend(list.into_iter().map(|r| r.refname));
    }

    let mut probe = SquashProbe::new(repo)?;
    let is_merged_local = |probe: &mut SquashProbe, refname: &str| -> anyhow::Result<bool> {
        for base in &bases {
            let set = ancestry_locals.get(&base.refname).unwrap();
            if probe.is_merged(git, &base.refname, refname, set)? {
                return Ok(true);
            }
        }
        Ok(false)
    };
    let is_merged_remote = |probe: &mut SquashProbe, refname: &str| -> anyhow::Result<bool> {
        for base in &bases {
            let set = ancestry_remotes.get(&base.refname).unwrap();
            if probe.is_merged(git, &base.refname, refname, set)? {
                return Ok(true);
            }
        }
        Ok(false)
    };

    // Worktrees: which branch is checked out where, and which one is ours.
    let worktrees = parse_worktrees(
        &git.worktree_list().map_err(anyhow::Error::from)?,
    );
    let current = repo.workdir().map(Path::new);
    let mut worktree_of: HashMap<&str, &Path> = HashMap::new();
    let mut head_branch: Option<String> = None;
    for (path, refname) in &worktrees {
        let is_current = current.map(|c| c == path.as_path()).unwrap_or(false);
        if is_current {
            head_branch = Some(refname.clone());
        } else {
            worktree_of.insert(refname.as_str(), path.as_path());
        }
    }

    // Classify local branches first, keeping the results around for their upstreams.
    let mut local_class: HashMap<&str, Class> = HashMap::new();
    for local in &locals {
        let class = match crate::branch::upstream_refname(repo, local, &refnames)? {
            Some(upstream) => {
                let merged_local = is_merged_local(&mut probe, &local.refname)?;
                let merged_upstream = is_merged_remote(&mut probe, &upstream.refname)?;
                if merged_local {
                    if merged_upstream {
                        Class::Merged
                    } else {
                        Class::Diverged(upstream.refname.clone())
                    }
                } else if merged_upstream {
                    Class::Stray
                } else {
                    Class::Stays
                }
            }
            None => {
                if is_merged_local(&mut probe, &local.refname)? {
                    Class::Merged
                } else {
                    Class::Stays
                }
            }
        };
        local_class.insert(local.refname.as_str(), class);
    }

    let upstream_of: HashMap<&str, Vec<&str>> = {
        let mut map: HashMap<&str, Vec<&str>> = HashMap::new();
        for local in &locals {
            if let Some(upstream) = crate::branch::upstream_refname(repo, local, &refnames)? {
                map.entry(upstream.refname.as_str())
                    .or_default()
                    .push(local.refname.as_str());
            }
        }
        map
    };

    let mut entries = Vec::new();
    for local in &locals {
        let upstream = crate::branch::upstream_refname(repo, local, &refnames)?;
        let class = local_class.get(local.refname.as_str()).cloned().unwrap();
        let base = bases
            .iter()
            .any(|b| Some(&b.refname) == upstream.as_ref().map(|u| &u.refname) || b.local.as_deref() == Some(local.refname.as_str()));
        let tracks_base = bases
            .iter()
            .find(|b| Some(&b.refname) == upstream.as_ref().map(|u| &u.refname))
            .map(|b| b.spec.clone());
        let worktree = worktree_of.get(local.refname.as_str()).map(|p| (*p).to_path_buf());
        let head = head_branch.as_deref() == Some(local.refname.as_str());
        entries.push(Entry {
            refname: local.refname.clone(),
            kind: Kind::Local {
                name: local.name.clone(),
                upstream: upstream.clone(),
            },
            class,
            tracked: false,
            base,
            tracks_base,
            protected_by: None,
            worktree,
            head,
        });
    }
    for remote in &remotes {
        let tracked = upstream_of.contains_key(remote.refname.as_str());
        let class = if tracked {
            let local_refname = upstream_of[remote.refname.as_str()][0];
            match local_class.get(local_refname) {
                Some(Class::Diverged(other)) if other == &remote.refname => Class::Diverged(local_refname.to_string()),
                Some(Class::Stray) => Class::Stray,
                _ => {
                    if is_merged_remote(&mut probe, &remote.refname)? {
                        Class::Merged
                    } else {
                        Class::Stays
                    }
                }
            }
        } else if is_merged_remote(&mut probe, &remote.refname)? {
            Class::Merged
        } else {
            Class::Stays
        };
        let base = bases.iter().any(|b| b.refname == remote.refname);
        entries.push(Entry {
            refname: remote.refname.clone(),
            kind: Kind::Remote {
                remote: remote.remote.clone(),
                name: remote.name.clone(),
            },
            class,
            tracked,
            base,
            tracks_base: None,
            protected_by: None,
            worktree: None,
            head: false,
        });
    }

    for entry in &mut entries {
        entry.protected_by = protect(protected, entry);
    }

    Ok(Scan {
        entries,
        bases,
        remote_heads,
    })
}

/// Names a branch is known by, in the order the protection check considers them.
fn names(entry: &Entry) -> Vec<String> {
    match &entry.kind {
        Kind::Local { name, .. } => vec![name.clone(), entry.refname.clone()],
        Kind::Remote { remote, name } => {
            vec![format!("{}/{}", remote, name), entry.refname.clone()]
        }
    }
}

fn protect(patterns: &[Pattern], entry: &Entry) -> Option<String> {
    if entry.base {
        return None;
    }
    for name in names(entry) {
        for pattern in patterns {
            if pattern.is_match(&name) {
                return Some(pattern.as_str().to_string());
            }
        }
    }
    None
}
RSEOF
echo ok

