                *markers.entry(*marker).or_default() += 1;
            }
        }
        println!("{}", line);
    }
    println!("  remote references:");
    for (i, entry) in scan.entries.iter().enumerate() {
        if !matches!(entry.kind, Kind::Remote { .. }) {
            continue;
        }
        let mut line = format!("    {}", display_name(entry));
        match &dispositions[i] {
            Disposition::Keep => {}
            Disposition::Delete => continue,
            Disposition::Skip(reason) => {
                line.push_str(&format!(
                    " [{}{}, but: {}]",
                    entry.status_prefix(),
                    "",
                    reason.describe()
                ));
            }
            Disposition::OutOfScope(marker) => {
                line.push_str(&format!(" *{}", marker.number()));
                *markers.entry(*marker).or_default() += 1;
                if *marker == Marker::Three {
                    skipped_remotes.push(entry);
                }
            }
        }
        println!("{}", line);
    }
    if !markers.is_empty() {
        println!("  Some branches are skipped. Consider following to scan them:");
        for (marker, _) in &markers {
            let remote = if *marker == Marker::Three {
                if skipped_remotes.len() == 1 {
                    skipped_remotes[0].remote_name().map(|s| s.to_string())
                } else {
                    None
                }
            } else {
                None
            };
            println!("    *{}: {}", marker.number(), marker.hint(remote.as_deref()));
        }
    }
    println!();

    // Collect the deletable entries, grouped per section.
    let mut sections: BTreeMap<Section, Vec<&Entry>> = BTreeMap::new();
    let mut candidates = Vec::new();
    for (i, entry) in scan.entries.iter().enumerate() {
        if !matches!(dispositions[i], Disposition::Delete) {
            continue;
        }
        let section = section_for(entry);
        candidates.push(Candidate {
            entry: i,
            section,
            range: candidate_range(entry).unwrap(),
            suffix: suffix_for(entry),
            remote: entry.remote_name().unwrap_or("").to_string(),
        });
        sections.entry(section).or_default().push(entry);
    }
    for (section, list) in &sections {
        println!("{}", section.header());
        let mut sorted: Vec<&Entry> = list.clone();
        sorted.sort_by(|a, b| a.refname.cmp(&b.refname));
        for entry in sorted {
            match &entry.kind {
                Kind::Local { .. } => {
                    println!("  - {}{}", display_name(entry), suffix_for(entry));
                }
                Kind::Remote { remote, .. } => {
                    println!("  - {}, {}{}", remote, entry.refname, suffix_for(entry));
                }
            }
        }
    }
    candidates
}

/// Simulate the detached checkout `git-trim` would perform, for dry runs.
pub fn print_detach_simulation(repo: &Repository, entry: &Entry) -> anyhow::Result<()> {
    let name = entry.local_name().unwrap_or("");
    let refname = format!("refs/heads/{}", name);
    let object = repo.revparse_single(&refname)?;
    let short = object.short_id()?;
    let commit = object.peel_to_commit()?;
    let summary = commit.summary().unwrap_or("").to_string();
    println!("Note: switching to '{}' (dry run)", refname);
    println!("You are in 'detached HED' state... blah blah...");
    println!("HEAD is now at {} {} (dry run)", short.as_str(), summary);
    Ok(())
}

/// Carry out the deletions.
pub fn delete(
    git: &Git,
    repo: &Repository,
    scan: &crate::scan::Scan,
    candidates: &[Candidate],
    dry_run: bool,
    detach: bool,
) -> anyhow::Result<()> {
    // Remote refs, grouped by remote.
    let mut per_remote: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for candidate in candidates {
        let entry = &scan.entries[candidate.entry];
        if let Kind::Remote { remote, .. } = &entry.kind {
            per_remote.entry(remote.as_str()).or_default().push(entry.refname.as_str());
        }
    }
    for (remote, refs) in &per_remote {
        let mut refs: Vec<&str> = refs.clone();
        refs.sort();
        git.push_delete(remote, &refs, dry_run)?;
    }

    let locals: Vec<&Entry> = candidates
        .iter()
        .map(|c| &scan.entries[c.entry])
        .filter(|e| matches!(e.kind, Kind::Local { .. }))
        .collect();

    if dry_run {
        for entry in &locals {
            if entry.head && detach {
                print_detach_simulation(repo, entry)?;
            }
        }
        let mut names: Vec<&str> = locals.iter().map(|e| e.local_name().unwrap()).collect();
        names.sort();
        for name in names {
            println!("Delete branch {} (dry run).", name);
        }
        return Ok(());
    }

    for entry in &locals {
        if entry.head && detach {
            let name = entry.local_name().unwrap();
            git.checkout_detached(&format!("refs/heads/{}", name))?;
        }
    }
    let mut names: Vec<&str> = locals.iter().map(|e| e.local_name().unwrap()).collect();
    names.sort();
    if !names.is_empty() {
        git.branch_delete(&names, dry_run)?;
    }
    Ok(())
}
