//! Rendering the report and carrying out (or simulating) the deletions.

use std::collections::BTreeMap;
use std::path::Path;

use anyhow::{anyhow, Context};
use git2::Repository;

use crate::branch::{Base, Class, Entry, Kind};
use crate::config::DeleteRange;
use crate::gitproc::Git;

/// Which section of the "Delete ..." report an entry belongs to.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Section {
    MergedLocal,
    MergedRemote,
    StrayLocal,
    DivergedRemote,
}

impl Section {
    fn header(self) -> &'static str {
        match self {
            Section::MergedLocal => "Delete merged local branches:",
            Section::MergedRemote => "Delete merged remote refs:",
            Section::StrayLocal => "Delete stray local branches:",
            Section::DivergedRemote => "Delete diverged remote refs:",
        }
    }
}

/// The `*N` marker shown for branches that are not scanned at all.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Marker {
    One,
    Two,
    Three,
}

impl Marker {
    fn number(self) -> u8 {
        match self {
            Marker::One => 1,
            Marker::Two => 2,
            Marker::Three => 3,
        }
    }

    fn hint(self, remote: Option<&str>) -> String {
        match self {
            Marker::One => "Add `--delete 'merged:*'` flag.".to_string(),
            Marker::Two => {
                "Set an upstream to make it a tracking branch or add `--delete 'local'` flag."
                    .to_string()
            }
            Marker::Three => format!(
                "Make it upstream of a tracking branch or add `--delete 'remote:{}'` flag.",
                remote.unwrap_or("*")
            ),
        }
    }
}

/// Why a branch is kept.
#[derive(Debug)]
enum Reason {
    Protected(String),
    Worktree(String),
    Head,
    RangeNotGiven(String),
}

impl Reason {
    fn describe(&self) -> String {
        match self {
            Reason::Protected(pattern) => {
                format!("protected by a pattern `{}`", pattern)
            }
            Reason::Worktree(path) => format!("worktree at {}", path.display()),
            Reason::Head => "HEAD".to_string(),
            Reason::RangeNotGiven(range) => format!("delete range `{}` was not given", range),
        }
    }
}

/// What `git-trim` decides to do with a branch.
#[derive(Debug)]
enum Disposition {
    /// Deletable with the given delete ranges.
    Delete,
    /// Scanned, but kept for a concrete reason.
    Skip(Reason),
    /// Not scanned at all.
    OutOfScope(Marker),
    /// Simply kept.
    Keep,
}

/// A branch that is going to be deleted.
#[derive(Debug)]
struct Candidate {
    entry: usize,
    section: Section,
    /// The delete range that removes this branch.
    range: DeleteRange,
    /// Suffix for the report line, e.g. ` (non-tracking)`.
    suffix: &'static str,
    /// Remote name, for remote refs.
    remote: String,
}

/// Names a branch is known by, in the order the protection check considers them.
fn names(entry: &Entry) -> Vec<String> {
    match &entry.kind {
        Kind::Local { name, .. } => vec![name.clone(), entry.refname.clone()],
        Kind::Remote { remote, name } => {
            vec![format!("{}/{}", remote, name), entry.refname.clone()]
        }
    }
}

fn display_name(entry: &Entry) -> String {
    match &entry.kind {
        Kind::Local { name, .. } => name.clone(),
        Kind::Remote { remote, name } => format!("{}/{}", remote, name),
    }
}

/// Is the given delete range satisfied by the configured ones?
fn range_given(ranges: &[DeleteRange], wanted: &DeleteRange) -> bool {
    match wanted {
        DeleteRange::MergedLocal => ranges
            .iter()
            .any(|r| matches!(r, DeleteRange::MergedLocal)),
        DeleteRange::Stray => ranges.iter().any(|r| matches!(r, DeleteRange::Stray)),
        DeleteRange::Local => ranges.iter().any(|r| matches!(r, DeleteRange::Local)),
        DeleteRange::MergedRemote(remote) => ranges
            .iter()
            .any(|r| matches!(r, DeleteRange::MergedRemote(r) if r == "*" || r == remote)),
        DeleteRange::Remote(remote) => ranges
            .iter()
            .any(|r| matches!(r, DeleteRange::Remote(r) if r == "*" || r == remote)),
        DeleteRange::Diverged(remote) => ranges
            .iter()
            .any(|r| matches!(r, DeleteRange::Diverged(r) if r == "*" || r == remote)),
    }
}

/// Is this branch in the scope of the configured delete ranges at all?
fn in_scope(entry: &Entry, ranges: &[DeleteRange]) -> bool {
    let tracked_pair = matches!(entry.kind, Kind::Local { upstream: Some(_), .. })
        || (matches!(entry.kind, Kind::Remote { .. }) && entry.tracked);
    if tracked_pair {
        return ranges.iter().any(|r| {
            matches!(
                r,
                DeleteRange::MergedLocal | DeleteRange::Stray | DeleteRange::MergedRemote(_)
            ) || matches!(r, DeleteRange::Diverged(_))
        });
    }
    match &entry.kind {
        Kind::Local { .. } => ranges.iter().any(|r| matches!(r, DeleteRange::Local)),
        Kind::Remote { remote, .. } => ranges
            .iter()
            .any(|r| matches!(r, DeleteRange::Remote(r) if r == "*" || r == remote)),
    }
}

/// The delete range that would remove this branch, when its class allows deletion.
fn candidate_range(entry: &Entry) -> Option<DeleteRange> {
    match (&entry.kind, &entry.class) {
        (Kind::Local { upstream, .. }, Class::Diverged(_)) => {
            upstream.as_ref().map(|u| DeleteRange::Diverged(u.remote.clone()))
        }
        (Kind::Local { upstream: Some(_), .. }, Class::Merged) => Some(DeleteRange::MergedLocal),
        (Kind::Local { .. }, Class::Merged) => Some(DeleteRange::Local),
        (Kind::Local { .. }, Class::Stray) => Some(DeleteRange::Stray),
        (Kind::Remote { remote, .. }, Class::Diverged(_)) => {
            Some(DeleteRange::Diverged(remote.clone()))
        }
        (Kind::Remote { remote, .. }, Class::Merged) => {
            if entry.tracked {
                Some(DeleteRange::MergedRemote(remote.clone()))
            } else {
                Some(DeleteRange::Remote(remote.clone()))
            }
        }
        _ => None,
    }
}

fn section_for(entry: &Entry) -> Section {
    match &entry.kind {
        Kind::Local { .. } => match entry.class {
            Class::Stray => Section::StrayLocal,
            _ => Section::MergedLocal,
        },
        Kind::Remote { .. } => match entry.class {
            Class::Diverged(_) => Section::DivergedRemote,
            _ => Section::MergedRemote,
        },
    }
}

fn suffix_for(entry: &Entry) -> &'static str {
    match (&entry.kind, &entry.class) {
        (Kind::Local { upstream: None, .. }, Class::Merged) => " (non-tracking)",
        (Kind::Remote { .. }, Class::Merged) if !entry.tracked => " (non-upstream)",
        _ => "",
    }
}

/// Compute what to do with every entry.
fn dispositions(scan: &crate::scan::Scan, ranges: &[DeleteRange], detach: bool) -> Vec<Disposition> {
    let entries = &scan.entries;
    let mut out = Vec::with_capacity(entries.len());
    // Index of the remote counterpart of a diverged local branch, and vice versa.
    let mut partner: BTreeMap<usize, usize> = BTreeMap::new();
    for (i, entry) in entries.iter().enumerate() {
        if let Class::Diverged(other) = &entry.class {
            if let Some(j) = entries.iter().position(|e| &e.refname == other) {
                partner.insert(i, j);
            }
        }
    }

    for (i, entry) in entries.iter().enumerate() {
        if entry.base {
            out.push(Disposition::Keep);
            continue;
        }
        if entry.tracks_base.is_some() {
            out.push(Disposition::Keep);
            continue;
        }
        if !in_scope(entry, ranges) {
            out.push(Disposition::OutOfScope(marker_for(entry)));
            continue;
        }
        let Some(range) = candidate_range(entry) else {
            out.push(Disposition::Keep);
            continue;
        };
        // A diverged pair shares its fate: reason and deletion both come from the pair.
        let mate = partner.get(&i).copied();
        let mut candidates: Vec<Option<&Entry>> = vec![Some(entry)];
        if let Some(j) = mate {
            candidates.push(entries.get(j));
        }
        let mut reason: Option<Reason> = None;
        for who in &candidates {
            let Some(who) = who else { continue };
            if reason.is_none() {
                if let Some(pattern) = &who.protected_by {
                    reason = Some(Reason::Protected(pattern.clone()));
                }
            }
        }
        if reason.is_none() {
            for who in &candidates {
                let Some(who) = who else { continue };
                if let Some(path) = &who.worktree {
                    reason = Some(Reason::Worktree(path.display().to_string()));
                    break;
                }
            }
        }
        if reason.is_none() {
            for who in &candidates {
                let Some(who) = who else { continue };
                if who.head && !detach {
                    reason = Some(Reason::Head);
                    break;
                }
            }
        }
        if reason.is_none() && !range_given(ranges, &range) {
            reason = Some(Reason::RangeNotGiven(range_string(&range)));
        }
        match reason {
            Some(reason) => out.push(Disposition::Skip(reason)),
            None => out.push(Disposition::Delete),
        }
    }
    out
}

fn range_string(range: &DeleteRange) -> String {
    match range {
        DeleteRange::MergedLocal => "merged-local".to_string(),
        DeleteRange::MergedRemote(r) => format!("merged-remote:{}", r),
        DeleteRange::Stray => "stray".to_string(),
        DeleteRange::Diverged(r) => format!("diverged:{}", r),
        DeleteRange::Local => "local".to_string(),
        DeleteRange::Remote(r) => format!("remote:{}", r),
    }
}

fn marker_for(entry: &Entry) -> Marker {
    match &entry.kind {
        Kind::Local { upstream, .. } => {
            if upstream.is_some() {
                Marker::One
            } else {
                Marker::Two
            }
        }
        Kind::Remote { .. } => {
            if entry.tracked {
                Marker::One
            } else {
                Marker::Three
            }
        }
    }
}

