//! The yes/no confirmation prompt, mirroring what `dialoguer` renders.

use std::io::{Read, Write};

use anyhow::{anyhow, Context};

/// Ask the user to confirm on stderr, returning `false` when the default is accepted.
pub fn confirm(prompt: &str, default: bool) -> anyhow::Result<bool> {
    let mut term = std::io::stderr();
    if !crate::tty::is_terminal(2) {
        return Err(not_a_terminal());
    }
    let rendered = format!("{} [y/N] ", prompt);
    let rendered = if default { rendered.replace("[y/N]", "[Y/n]") } else { rendered };
    term.write_all(rendered.as_bytes())?;
    term.write_all(b"\x1b[?25l")?;
    term.flush()?;

    let answer = loop {
        let key = read_key()?;
        match key {
            'y' | 'Y' => break true,
            'n' | 'N' => break false,
            '\n' | '\r' => break default,
            _ => continue,
        }
    };

    term.write_all(b"\r\x1b[2K")?;
    term.write_all(if answer { "yes" } else { "no" }.as_bytes())?;
    term.write_all(b"\n")?;
    term.write_all(b"\x1b[?25h")?;
    term.flush()?;
    Ok(answer)
}

fn not_a_terminal() -> anyhow::Error {
    anyhow!("not a terminal")
}

fn read_key() -> anyhow::Result<char> {
    if !crate::tty::is_terminal(0) {
        return Err(not_a_terminal());
    }
    let saved = crate::tty::get_termios(0).map_err(|err| anyhow!("{}", err))?;
    crate::tty::set_raw(0, &saved).map_err(|err| anyhow!("{}", err))?;
    let result = read_char();
    crate::tty::set_termios(0, &saved).map_err(|err| anyhow!("{}", err))?;
    result
}

fn read_char() -> anyhow::Result<char> {
    let mut stdin = std::io::stdin();
    let mut buf = [0u8; 1];
    loop {
        let read = stdin.read(&mut buf)?;
        if read == 0 {
            return Ok('\n');
        }
        if buf[0] == b'\x1b' {
            // Escape sequences are swallowed.
            let mut byte = [0u8; 1];
            if stdin.read(&mut byte)? == 0 {
                continue;
            }
            if byte[0] == b'[' || byte[0] == b'O' {
                let mut byte = [0u8; 1];
                if stdin.read(&mut byte)? == 0 {
                    continue;
                }
            }
            continue;
        }
        if buf[0] & 0x80 == 0 {
            return Ok(buf[0] as char);
        }
        // Multi byte characters are not interesting for a y/n prompt.
        continue;
    }
}

/// Wrap a prompt error the way `git-trim` reports it.
pub fn confirm_or_cancel(prompt: &str, default: bool) -> anyhow::Result<bool> {
    confirm(prompt, default).map_err(|err| {
        err.context(format!("IO error: {}", err.root_cause()))
    })
