//! `git-trim` - automatically trims tracking branches whose upstream branches are merged or stray.

mod branch;
mod cli;
mod config;
mod glob;
mod gitproc;
mod prompt;
mod remote;
mod report;
mod scan;
mod tty;

use std::collections::BTreeMap;

use anyhow::{anyhow, bail};
use clap::ArgMatches;
use git2::Repository;

use crate::cli::command;
use crate::config::{DeleteRange, TrimConfig};
use crate::glob::Pattern;
use crate::gitproc::Git;
use crate::remote::Remote;

/// The parsed command line.
#[derive(Debug, Default)]
struct Args {
    bases: Option<Vec<String>>,
    protected: Option<Vec<String>>,
    no_update: bool,
    update_interval: Option<i64>,
    no_confirm: bool,
    no_detach: bool,
    delete: Option<Vec<crate::config::DeleteToken>>,
    dry_run: bool,
}

impl Args {
    fn from_matches(matches: &ArgMatches) -> Self {
        let opt_vec = |name: &str| -> Option<Vec<String>> {
            matches
                .get_many::<String>(name)
                .map(|values| values.map(|v| v.to_string()).collect())
        };
        Args {
            bases: opt_vec("bases"),
            protected: opt_vec("protected"),
            no_update: matches.get_flag("no-update"),
            update_interval: matches.get_one::<i64>("update-interval").copied(),
            no_confirm: matches.get_flag("no-confirm"),
            no_detach: matches.get_flag("no-detach"),
            delete: matches
                .get_many::<crate::config::DeleteToken>("delete")
                .map(|values| values.cloned().collect()),
            dry_run: matches.get_flag("dry-run"),
        }
    }
}

fn non_empty(values: &Option<Vec<String>>) -> Option<Vec<String>> {
    let values = values.as_ref()?;
    let filtered: Vec<String> = values.iter().filter(|v| !v.is_empty()).cloned().collect();
    if filtered.is_empty() {
        None
    } else {
        Some(filtered)
    }
}

fn main() -> anyhow::Result<()> {
    let matches = command().get_matches();
    let args = Args::from_matches(&matches);
    run(&args)
}

fn hints_no_remote() -> Vec<String> {
    Vec::new()
}

/// Print the "I can't detect base branch" resolution hints.
fn print_base_hints(remotes: &[Remote]) {
    eprintln!("I can't detect base branch! Try following any resolution:");
    if remotes.len() == 1 {
        eprintln!(
            " * `git remote set-head {} --auto` will help `git-trim` to automatically",
            remotes[0].name
        );
        eprintln!("   detect the base branch.");
        eprintln!(
            "   If you see `{}HEAD set to <base branch>` in the output of the previous",
            format!("{}/", remotes[0].name)
        );
        eprintln!(
            "   command, then `git branch --set-upstream {}/<base branch> <base branch>`",
            remotes[0].name
        );
        eprintln!(
            "   to set an upstream branch for <base branch> if exists."
        );
    } else {
        eprintln!(" * `git remote set-head <remote> --auto` will help `git-trim` to automatically");
        eprintln!("   detect the base branch.");
        eprintln!("   Following command will sync all remotes for you:");
        eprintln!("   `for REMOTE in $(git remote); do git remote set-head \"$REMOTE\" --auto; done`");
        eprintln!("   Pick an appropriate one in mind if you see multiple `<remote>/HEAD set to");
        eprintln!("   <base branch>` in the output of the previous command.");
        eprintln!("   Then `git branch --set-upstream <remote>/<base branch> <base branch>` to set");
        eprintln!("   an upstream branch for <base branch> if exists.");
    }
    eprintln!(" * `git config trim.bases develop,master` for a repository.");
    eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
    eprintln!(" * `git trim --bases develop,master` to set temporarily.");
}

fn run(args: &Args) -> anyhow::Result<()> {
    let repo = Repository::discover(".")?;
    let config = config::read(&repo.config()?)?;

    let update = if args.no_update { false } else { config.update };
    let confirm = if args.no_confirm { false } else { config.confirm };
    let detach = if args.no_detach { false } else { config.detach };
    let update_interval = args.update_interval.or(config.update_interval).unwrap_or(5);
    let _ = update_interval;

    let ranges: Vec<DeleteRange> = match &args.delete {
        Some(tokens) => crate::config::expand_tokens(tokens)?,
        None => match &config.delete {
            Some(ranges) => ranges.clone(),
            None => DeleteRange::expand("merged:origin")?,
        },
    };
    let protected: Vec<Pattern> = match non_empty(&args.protected) {
        Some(values) => values.into_iter().map(Pattern::new).collect(),
        None => config.protected.clone().unwrap_or_default(),
    };

    let remotes = remote::list(&repo)?;
    if remotes.is_empty() {
        bail!("git-trim requires at least one remote");
    }
    let workdir = repo.workdir()?.to_path_buf();
    let git = Git::new(&workdir);

    let mut remote_heads: BTreeMap<String, anyhow::Result<String>> = BTreeMap::new();
    if update {
        remote::update(&git, &remotes, args.dry_run)?;
        remote_heads = remote::heads(&git, &remotes);
        println!();
    }

    let (locals, remotes_ref) = branch::list_refs(&repo)?;
    let remote_names: Vec<String> = remotes.iter().map(|r| r.name.clone()).collect();
    let explicit = non_empty(&args.bases).or(config.bases.clone());
    let default_bases = explicit.is_none();
    let bases = scan::bases(
        &repo,
        &locals,
        &remotes_ref,
        &remote_names,
        explicit.as_deref(),
        default_bases,
    )?;
    if bases.is_empty() && default_bases {
        print_base_hints(&remotes);
        println!("You also can set bases manually with any of following commands:");
        bail!("No base branch is found!");
    }

    let scan = scan::run(
        &repo,
        &git,
        &config,
        explicit.as_deref(),
        &protected,
        args.dry_run,
        &remote_names,
        remote_heads,
    )?;

    let candidates = report::print(&scan, &ranges, detach);

    if !candidates.is_empty() && confirm && !args.dry_run_noop() {
        let confirmed = prompt::confirm_or_cancel("Confirm?", false)?;
        if !confirmed {
            println!("Cancelled");
            return Ok(());
        }
    }

    report::delete(&git, &repo, &scan, &candidates, args.dry_run, detach)?;

    check_remote_heads(&scan, &remote_names, default_bases)?;
    Ok(())
}

impl Args {
    fn dry_run_noop(&self) -> bool {
        false
    }
}

/// Compare the remote HEAD symrefs with the locally tracked ones and warn about drift.
fn check_remote_heads(
    scan: &crate::scan::Scan,
    remote_names: &[String],
    default_bases: bool,
) -> anyhow::Result<()> {
    if scan.remote_heads.is_empty() {
        return Ok(());
    }
    for name in remote_names {
        scan.remote_heads
            .get(name)
            .ok_or_else(|| anyhow!("missing remote head for {}", name))?
            .as_ref()
            .map_err(|err| anyhow!("{}", err))?;
    }
    if !default_bases {
        return Ok(());
    }
    let mut drifted: Vec<(String, String, String)> = Vec::new();
    let mut sync: Vec<String> = Vec::new();
    for name in remote_names {
        let symref = scan
            .remote_heads
            .get(name)
            .and_then(|r| r.as_ref().ok())
            .cloned();
        let Some(symref) = symref else { continue };
        let prefix = format!("refs/remotes/{}/", name);
        let branch = match symref.strip_prefix("refs/heads/") {
            Some(branch) => branch.to_string(),
            None => continue,
        };
        let local = match branch::local_head_target(&repo_of(name), name, &branch) {
            Some(local) => local,
            None => continue,
        };
        if local != symref {
            drifted.push((name.clone(), local, symref.clone()));
            sync.push(format!(" > git remote set-head {} --auto", name));
        }
    }
    if drifted.is_empty() {
        return Ok(());
    }
    eprintln!("You are using default base branches, which is deduced from `refs/remotes/*/HEAD`s.");
    eprintln!("However, they seems to be out of sync.");
    for (remote, local, remote_head) in &drifted {
        eprintln!(" * {}: {} -> {}", remote, local, remote_head);
    }
    eprintln!("You can sync them with these commands:");
    for line in &sync {
        eprintln!("{}", line);
    }
    eprintln!("Or you can set base branches manually:");
    eprintln!(" * `git config trim.bases develop,master` will set base branches for git-trim for a repository.");
    eprintln!(" * `git config --global trim.bases develop,master` will set base branches for `git-trim` globally.");
    eprintln!(" * `git trim --bases develop,master` will temporarily set base branches for `git-trim`");
    Ok(())
}
