//! The yes/no confirmation prompt, mirroring what `dialoguer` renders on stderr.

use std::io::{Read, Write};

use anyhow::{anyhow, Context};
use git2::Error as GitError;

use crate::tty;

/// Ask the user to confirm.  `Err` when the terminal is not usable.
pub fn confirm(prompt: &str, default: bool) -> anyhow::Result<bool> {
    if !tty::is_terminal(2) {
        return Err(not_a_terminal());
    }
    let mut term = std::io::stderr();
    let marker = if default { "[Y/n]" } else { "[y/N]" };
    let rendered = format!("{} {} ", prompt, marker);
    term.write_all(rendered.as_bytes())?;
    term.write_all(b"\x1b[?25l")?;
    term.flush()?;

    let answer = loop {
        let key = read_key().map_err(wrap)?;
        match key {
            'y' | 'Y' => break true,
            'n' | 'N' => break false,
            '\n' | '\r' => break default,
            _ => continue,
        }
    };

    term.write_all(b"\r\x1b[2K")?;
    term.write_all(if answer { b"yes" } else { b"no" })?;
    term.write_all(b"\n")?;
    term.write_all(b"\x1b[?25h")?;
    term.flush()?;
    Ok(answer)
}

fn not_a_terminal() -> anyhow::Error {
    anyhow!("not a terminal")
}

/// Reproduce the error chain `git-trim` prints for prompt failures.
fn wrap(err: std::io::Error) -> anyhow::Error {
    anyhow::Error::new(err).context(format!("IO error: {}", err))
}

fn read_key() -> std::io::Result<char> {
    if !tty::is_terminal(0) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::NotConnected,
            "not a terminal",
        ));
    }
    let saved = tty::get_termios(0)?;
    tty::set_raw(0, &saved)?;
    let result = read_char();
    let _ = tty::set_termios(0, &saved);
    result
}

fn read_char() -> std::io::Result<char> {
    let mut stdin = std::io::stdin();
    let mut buf = [0u8; 1];
    loop {
        let read = stdin.read(&mut buf)?;
        if read == 0 {
            return Ok('\n');
        }
        match buf[0] {
            b'\x1b' => {
                // Swallow escape sequences, they are not part of an answer.
                let mut byte = [0u8; 1];
                if stdin.read(&mut byte)? == 0 {
                    continue;
                }
                if byte[0] == b'[' || byte[0] == b'O' {
                    let mut byte = [0u8; 1];
                    if stdin.read(&mut byte)? == 0 {
                        continue;
                    }
                }
                continue;
            }
            b'\x03' => return Err(std::io::Error::new(std::io::ErrorKind::Interrupted, "interrupted")),
            _ if buf[0] & 0x80 == 0 => return Ok(buf[0] as char),
            _ => continue,
        }
    }
}

/// The `git2` error type is re-exported so callers can match on it.
pub type _Unused = GitError;
