/// Run the whole scan.
#[allow(clippy::too_many_arguments)]
pub fn run(
    repo: &Repository,
    git: &Git,
    _config: &TrimConfig,
    explicit_bases: Option<&[String]>,
    protected: &[Pattern],
    remote_names: &[String],
    remote_heads: BTreeMap<String, anyhow::Result<String>>,
) -> anyhow::Result<Scan> {
