    let refnames: HashSet<String> = crate::branch::all_refnames(repo)?;
    let refnames: HashSet<&str> = refnames.iter().map(|s| s.as_str()).collect();
    let bases = bases(repo, &locals, &remotes, remote_names, explicit_bases)?;

