        let merged = {
            let mut result = false;
            for base in &bases {
                let empty: HashSet<String> = HashSet::new();
                let set = ancestry_locals.get(&base.refname).unwrap_or(&empty);
                if probe.is_merged(git, &base.refname, &local.refname, set)? {
                    result = true;
                    break;
                }
            }
            result
        };
        merged_local.insert(local.refname.clone(), merged);
        if let Some(upstream) = &upstream {
            let merged = {
                let mut result = false;
                for base in &bases {
                    let empty: HashSet<String> = HashSet::new();
                    let set = ancestry_remotes.get(&base.refname).unwrap_or(&empty);
                    if probe.is_merged(git, &base.refname, &upstream.refname, set)? {
                        result = true;
                        break;
                    }
                }
                result
            };
            merged_remote.insert(upstream.refname.clone(), merged);
        }
    }
    for remote in &remotes {
        if merged_remote.contains_key(&remote.refname) {
            continue;
        }
        let merged = {
            let mut result = false;
            for base in &bases {
                let empty: HashSet<String> = HashSet::new();
                let set = ancestry_remotes.get(&base.refname).unwrap_or(&empty);
                if probe.is_merged(git, &base.refname, &remote.refname, set)? {
                    result = true;
                    break;
                }
