            .iter()
            .any(|b| b.local.as_deref() == Some(local.refname.as_str()));
        let tracks_base = bases
            .iter()
            .find(|b| Some(&b.refname) == upstream.as_ref().map(|u| &u.refname))
            .map(|b| b.spec.clone());
