//! figuring out which ones `git-trim` would delete.

use std::collections::{BTreeMap, HashMap, HashSet};
use std::path::Path;

use git2::Repository;

use crate::branch::{
    parse_merged_locals, parse_merged_remotes, parse_worktrees, remote_head_target, upstream_refname,
    Base, Class, Entry, Kind, LocalRef, RemoteRef, SquashProbe,
};
use crate::config::TrimConfig;
use crate::glob::Pattern;
use crate::gitproc::Git;

/// Everything we learned about the repository in one pass.
pub struct Scan {
    /// Branch entries, in the order the repository reports its references.
    pub entries: Vec<Entry>,
    /// The base branches the analysis used.
    pub bases: Vec<Base>,
    /// Remote HEAD symrefs as the remote reports them.
    pub remote_heads: BTreeMap<String, anyhow::Result<String>>,
    /// The local branch each remote's `refs/remotes/<remote>/HEAD` points at.
    pub remote_local_heads: BTreeMap<String, Option<String>>,
}

/// Resolve `--bases` / `trim.bases` / `refs/remotes/*/HEAD` into the list of base branches.
pub fn bases(
    repo: &Repository,
    locals: &[LocalRef],
    remotes: &[RemoteRef],
    remote_names: &[String],
    explicit: Option<&[String]>,
) -> anyhow::Result<Vec<Base>> {
    let local_by_name: HashMap<&str, &LocalRef> =
        locals.iter().map(|l| (l.name.as_str(), l)).collect();
    let refnames: HashSet<&str> = remotes.iter().map(|r| r.refname.as_str()).collect();
    let mut out: Vec<Base> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();

    if let Some(specs) = explicit {
        for spec in specs {
            let reference = match repo.resolve_reference_from_short_name(spec) {
                Ok(reference) => reference,
                Err(err) if err.code() == git2::ErrorCode::NotFound => continue,
                Err(err) => return Err(anyhow::Error::new(err)),
            };
            let name = reference.name()?.to_string();
            let base = if let Some(name) = name.strip_prefix("refs/heads/") {
                let Some(local) = local_by_name.get(name) else {
                    continue;
                };
                let Some(upstream) = upstream_refname(repo, local, &refnames)? else {
                    continue;
                };
                Base {
                    spec: spec.to_string(),
                    refname: upstream.refname.clone(),
                    local: Some(local.refname.clone()),
                }
            } else if name.starts_with("refs/remotes/") {
                Base {
                    spec: spec.to_string(),
                    refname: name.clone(),
                    local: None,
                }
            } else {
                continue;
            };
            if seen.insert(base.refname.clone()) {
                out.push(base);
            }
        }
        return Ok(out);
    }

    for remote in remote_names {
        let head_refname = format!("refs/remotes/{}/HEAD", remote);
        let reference = match repo.find_reference(&head_refname) {
            Ok(reference) => reference,
            Err(_) => continue,
        };
        let Some(target) = reference.symbolic_target()? else {
            continue;
        };
        let prefix = format!("refs/remotes/{}/", remote);
        let Some(branch) = target.strip_prefix(&prefix) else {
            continue;
        };
        let refname = match local_by_name.get(branch) {
            Some(local) => match upstream_refname(repo, local, &refnames)? {
                Some(upstream) => upstream.refname,
                None => target.clone(),
            },
            None => target.clone(),
        };
        if !seen.insert(branch.to_string()) {
            continue;
        }
        out.push(Base {
            spec: branch.to_string(),
            refname,
            local: local_by_name.get(branch).map(|l| l.refname.clone()),
        });
    }
    Ok(out)
}

/// Run the whole scan.
#[allow(clippy::too_many_arguments)]
pub fn run(
    repo: &Repository,
    git: &Git,
    _config: &TrimConfig,
    explicit_bases: Option<&[String]>,
    protected: &[Pattern],
    remote_names: &[String],
    remote_heads: BTreeMap<String, anyhow::Result<String>>,
) -> anyhow::Result<Scan> {
    let (locals, remotes) = crate::branch::list_refs(repo)?;
    let refnames: HashSet<String> = crate::branch::all_refnames(repo)?;
    let refnames: HashSet<&str> = refnames.iter().map(|s| s.as_str()).collect();
    let bases = bases(repo, &locals, &remotes, remote_names, explicit_bases)?;

    let mut ancestry_locals: HashMap<String, HashSet<String>> = HashMap::new();
    let mut ancestry_remotes: HashMap<String, HashSet<String>> = HashMap::new();
    for base in &bases {
        let output = git
            .merged_refs(&base.refname, false)
            .map_err(anyhow::Error::from)?;
        let list = parse_merged_locals(repo, &output)?;
        ancestry_locals
            .entry(base.refname.clone())
            .or_default()
            .extend(list.into_iter().map(|l| l.refname));
        let output = git
            .merged_refs(&base.refname, true)
            .map_err(anyhow::Error::from)?;
        let list = parse_merged_remotes(repo, &output)?;
        ancestry_remotes
            .entry(base.refname.clone())
            .or_default()
            .extend(list.into_iter().map(|r| r.refname));
    }

    let mut probe = SquashProbe::new(repo)?;
    let mut merged_local: HashMap<String, bool> = HashMap::new();
    let mut merged_remote: HashMap<String, bool> = HashMap::new();

    for local in &locals {
        let upstream = upstream_refname(repo, local, &refnames)?;
        let merged = {
            let mut result = false;
            for base in &bases {
                let empty: HashSet<String> = HashSet::new();
                let set = ancestry_locals.get(&base.refname).unwrap_or(&empty);
                if probe.is_merged(git, &base.refname, &local.refname, set)? {
                    result = true;
                    break;
                }
            }
            result
        };
        merged_local.insert(local.refname.clone(), merged);
        if let Some(upstream) = &upstream {
            let merged = {
                let mut result = false;
                for base in &bases {
                    let empty: HashSet<String> = HashSet::new();
                    let set = ancestry_remotes.get(&base.refname).unwrap_or(&empty);
                    if probe.is_merged(git, &base.refname, &upstream.refname, set)? {
                        result = true;
                        break;
                    }
                }
                result
            };
            merged_remote.insert(upstream.refname.clone(), merged);
        }
    }
    for remote in &remotes {
        if merged_remote.contains_key(&remote.refname) {
            continue;
        }
        let merged = {
            let mut result = false;
            for base in &bases {
                let empty: HashSet<String> = HashSet::new();
                let set = ancestry_remotes.get(&base.refname).unwrap_or(&empty);
                if probe.is_merged(git, &base.refname, &remote.refname, set)? {
                    result = true;
                    break;
                }
            }
            result
        };
        merged_remote.insert(remote.refname.clone(), merged);
    }

    // Worktrees: which branch is checked out where, and which one is ours.
    let worktrees = parse_worktrees(&git.worktree_list().map_err(anyhow::Error::from)?);
    let current = repo.workdir().map(Path::new);
    let mut worktree_of: HashMap<&str, &Path> = HashMap::new();
    let mut head_branch: Option<&str> = None;
    for (path, refname) in &worktrees {
        let is_current = current.map(|c| c == path.as_path()).unwrap_or(false);
        if is_current {
            head_branch = Some(refname.as_str());
        } else {
            worktree_of.insert(refname.as_str(), path.as_path());
        }
    }

    let mut entries = Vec::new();
    for local in &locals {
        let upstream = upstream_refname(repo, local, &refnames)?;
        let merged = merged_local[&local.refname];
        let class = match &upstream {
            Some(upstream) => {
                let upstream_merged = merged_remote[&upstream.refname];
                if merged {
                    if upstream_merged {
                        Class::Merged
                    } else {
                        Class::Diverged(upstream.refname.clone())
                    }
                } else if upstream_merged {
                    Class::Stray
                } else {
                    Class::Stays
                }
            }
            None => {
                if merged {
                    Class::Merged
                } else {
                    Class::Stays
                }
            }
        };
        let base = bases
            .iter()
            .any(|b| b.local.as_deref() == Some(local.refname.as_str()));
        let tracks_base = bases
            .iter()
            .find(|b| Some(&b.refname) == upstream.as_ref().map(|u| &u.refname))
            .map(|b| b.spec.clone());
        let worktree = worktree_of
            .get(local.refname.as_str())
            .map(|p| (*p).to_path_buf());
        let head = head_branch == Some(local.refname.as_str());
        entries.push(Entry {
            refname: local.refname.clone(),
            kind: Kind::Local {
                name: local.name.clone(),
                upstream: upstream.clone(),
            },
            class,
            tracked: false,
            base,
            tracks_base,
            protected_by: None,
            worktree,
            head,
        });
    }
    for remote in &remotes {
        let tracked = merged_remote.contains_key(&remote.refname);
        let class = if tracked {
            // The local branch tracking this ref, if we know about it.
            let mut owner: Option<&LocalRef> = None;
            for local in &locals {
                if let Some(upstream) = upstream_refname(repo, local, &refnames)? {
                    if upstream.refname == remote.refname {
                        owner = Some(local);
                        break;
                    }
                }
            }
            match owner {
                Some(local) => {
                    if merged_remote[&remote.refname] {
                        Class::Merged
                    } else if merged_local[&local.refname] {
                        Class::Diverged(local.refname.clone())
                    } else {
                        Class::Stays
                    }
                }
                None => {
                    if merged_remote[&remote.refname] {
                        Class::Merged
                    } else {
                        Class::Stays
                    }
                }
            }
        } else {
            Class::Stays
        };
        let base = bases.iter().any(|b| b.refname == remote.refname);
        entries.push(Entry {
            refname: remote.refname.clone(),
            kind: Kind::Remote {
                remote: remote.remote.clone(),
                name: remote.name.clone(),
            },
            class,
            tracked,
            base,
            tracks_base: None,
            protected_by: None,
            worktree: None,
            head: false,
        });
    }

    for entry in &mut entries {
        entry.protected_by = protect(protected, entry);
    }

    let mut remote_local_heads = BTreeMap::new();
    for name in remote_names {
        remote_local_heads.insert(name.clone(), remote_head_target(repo, name, &remotes)?);
    }

    Ok(Scan {
        entries,
        bases,
        remote_heads,
        remote_local_heads,
    })
}

/// Names a branch is known by, in the order the protection check considers them.
fn names(entry: &Entry) -> Vec<String> {
    match &entry.kind {
        Kind::Local { name, .. } => vec![name.clone(), entry.refname.clone()],
        Kind::Remote { remote, name } => {
            vec![format!("{}/{}", remote, name), entry.refname.clone()]
        }
    }
}

fn protect(patterns: &[Pattern], entry: &Entry) -> Option<String> {
    if entry.base {
        return None;
    }
    for name in names(entry) {
        for pattern in patterns {
            if pattern.is_match(&name) {
                return Some(pattern.as_str().to_string());
            }
        }
    }
    None
}
