//! Scanning a repository: enumerating branches, classifying them against the base branches and
//! figuring out which ones `git-trim` would delete.

use std::collections::{BTreeMap, HashMap, HashSet};
use std::path::Path;

use anyhow::Context;
use git2::Repository;

use crate::branch::{
    parse_merged_locals, parse_merged_remotes, parse_worktrees, remote_head_target, upstream_refname,
    Base, Class, Entry, Kind, LocalRef, RemoteRef, SquashProbe, TrackingBranchClassificationRequest,
};
use crate::config::{DeleteRange, TrimConfig};
use crate::glob::Pattern;
use crate::gitproc::Git;

/// Everything we learned about the repository in one pass.
pub struct Scan {
    /// Branch entries, in the order the repository reports its references.
    pub entries: Vec<Entry>,
    /// The base branches the analysis used.
    pub bases: Vec<Base>,
    /// Remote HEAD symrefs as the remote reports them.
    pub remote_heads: BTreeMap<String, anyhow::Result<String>>,
    /// The local branch each remote's `refs/remotes/<remote>/HEAD` points at.
    pub remote_local_heads: BTreeMap<String, Option<String>>,
}

/// Resolve `--bases` / `trim.bases` / `refs/remotes/*/HEAD` into the list of base branches.
pub fn bases(
    repo: &Repository,
    locals: &[LocalRef],
    remotes: &[RemoteRef],
    remote_names: &[String],
    explicit: Option<&[String]>,
) -> anyhow::Result<Vec<Base>> {
    let local_by_name: HashMap<&str, &LocalRef> =
        locals.iter().map(|l| (l.name.as_str(), l)).collect();
    let refnames: HashSet<String> = remotes.iter().map(|r| r.refname.clone()).collect();
    let mut out: Vec<Base> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();

    if let Some(specs) = explicit {
        for spec in specs {
            let reference = match repo.resolve_reference_from_short_name(spec) {
                Ok(reference) => reference,
                Err(err) if err.code() == git2::ErrorCode::NotFound => continue,
                Err(err) => return Err(anyhow::Error::new(err)),
            };
            let name = reference.name()?.to_string();
            let base = if let Some(name) = name.strip_prefix("refs/heads/") {
                let Some(local) = local_by_name.get(name) else {
                    continue;
                };
                let Some(upstream) = upstream_refname(repo, local, &refnames)? else {
                    continue;
                };
                Base {
                    spec: spec.to_string(),
                    refname: upstream.refname.clone(),
                    local: Some(local.refname.clone()),
                }
            } else if name.starts_with("refs/remotes/") {
                Base {
                    spec: spec.to_string(),
                    refname: name.clone(),
                    local: None,
                }
            } else {
                continue;
            };
            if seen.insert(base.refname.clone()) {
                out.push(base);
            }
        }
        return Ok(out);
    }

    for remote in remote_names {
        let head_refname = format!("refs/remotes/{}/HEAD", remote);
        let reference = match repo.find_reference(&head_refname) {
            Ok(reference) => reference,
            Err(_) => continue,
        };
        let Some(target) = reference.symbolic_target()? else {
            continue;
        };
        let prefix = format!("refs/remotes/{}/", remote);
        let Some(branch) = target.strip_prefix(&prefix) else {
            continue;
        };
        let refname = match local_by_name.get(branch) {
            Some(local) => match upstream_refname(repo, local, &refnames)? {
                Some(upstream) => upstream.refname,
                None => target.to_string(),
            },
            None => target.to_string(),
        };
        if !seen.insert(branch.to_string()) {
            continue;
        }
        out.push(Base {
            spec: branch.to_string(),
            refname,
            local: local_by_name.get(branch).map(|l| l.refname.clone()),
        });
    }
    Ok(out)
}

/// Is this delete range part of the configured set, regardless of the remote it names?
fn any_of(ranges: &[DeleteRange], wanted: &[&str]) -> bool {
    ranges.iter().any(|r| {
        wanted.iter().any(|w| match (r, *w) {
            (DeleteRange::MergedLocal, "merged-local") => true,
            (DeleteRange::Stray, "stray") => true,
            (DeleteRange::MergedRemote(_), "merged-remote") => true,
            (DeleteRange::Diverged(_), "diverged") => true,
            (DeleteRange::Local, "local") => true,
            (DeleteRange::Remote(_), "remote") => true,
            _ => false,
        })
    })
}

/// Does `ranges` contain a range that could ever apply to this branch?
fn in_scope(entry: &Entry, ranges: &[DeleteRange]) -> bool {
    let tracked_pair = matches!(entry.kind, Kind::Local { upstream: Some(_), .. })
        || (matches!(entry.kind, Kind::Remote { .. }) && entry.tracked);
    if tracked_pair {
        return any_of(ranges, &["merged-local", "stray", "merged-remote", "diverged"]);
    }
    match &entry.kind {
        Kind::Local { .. } => any_of(ranges, &["local"]),
        Kind::Remote { remote, .. } => ranges
            .iter()
            .any(|r| matches!(r, DeleteRange::Remote(r) if r == "*" || r == remote)),
    }
}

/// Run the whole scan.
#[allow(clippy::too_many_arguments)]
pub fn run(
    repo: &Repository,
    git: &Git,
    _config: &TrimConfig,
    explicit_bases: Option<&[String]>,
    protected: &[Pattern],
    remote_names: &[String],
    remote_heads: BTreeMap<String, anyhow::Result<String>>,
    ranges: &[DeleteRange],
) -> anyhow::Result<Scan> {
    let (locals, remotes) = crate::branch::list_refs(repo)?;
    let refnames: HashSet<String> = crate::branch::all_refnames(repo)?;
    let bases = bases(repo, &locals, &remotes, remote_names, explicit_bases)?;
    let base_refnames: HashSet<&str> = bases.iter().map(|b| b.refname.as_str()).collect();

    let upstream_of: HashMap<&str, RemoteRef> = {
        let mut map = HashMap::new();
        for local in &locals {
            if let Some(upstream) = upstream_refname(repo, local, &refnames)? {
                map.insert(local.refname.as_str(), upstream);
            }
        }
        map
    };
    let tracked_by: HashMap<&str, &LocalRef> = {
        let mut map = HashMap::new();
        for local in &locals {
            if let Some(upstream) = upstream_of.get(local.refname.as_str()) {
                map.insert(upstream.refname.as_str(), local);
            }
        }
        map
    };

    // Which refs are worth testing at all: everything in scope, except base branches and the
    // branches that track them.
    let mut probe = SquashProbe::new(repo)?;
    let mut merged: HashMap<String, bool> = HashMap::new();
    let mut pending: Vec<(usize, String)> = Vec::new();
    let mut tested: Vec<&str> = Vec::new();

    let mut consider = |probe: &mut SquashProbe,
                        refname: &str,
                        skip: bool,
                        base_index: &mut usize,
                        pending: &mut Vec<(usize, String)>,
                        merged: &mut HashMap<String, bool>,
                        tested: &mut Vec<&str>| -> anyhow::Result<()> {
        if skip || merged.contains_key(refname) {
            return Ok(());
        }
        let mut result = false;
        let mut index = 0usize;
        for base in &bases {
            if base_refnames.contains(base.refname.as_str()) {
                continue;
            }
            if ancestry_local_contains(&ancestry_locals, &base.refname, refname) {
                result = true;
                break;
            }
            let direct = probe_direct(probe, git, &base.refname, refname)?;
            if direct {
                result = true;
                break;
            }
            pending.push((index, refname.to_string()));
            index += 1;
        }
        let _ = base_index;
        merged.insert(refname.to_string(), result);
        tested.push(refname);
        Ok(())
    };

    let _ = &mut consider;
    // Phase 1: the direct cherry-pick analysis, then phase 2: the squash-merge probes.
    for local in &locals {
        let upstream = upstream_of.get(local.refname.as_str());
        let skip = base_refnames.contains(local.refname.as_str());
        let in_scope = in_scope_local(&upstream, ranges);
        consider_probe(
            &mut probe,
            git,
            &bases,
            &ancestry_locals,
            local.refname.as_str(),
            skip || !in_scope,
            &mut merged,
        )?;
        if let Some(upstream) = upstream {
            let skip = base_refnames.contains(upstream.refname.as_str());
            consider_probe(
                &mut probe,
                git,
                &bases,
                &ancestry_remotes,
                upstream.refname.as_str(),
                skip,
                &mut merged,
            )?;
        }
    }
    for remote in &remotes {
        let skip = base_refnames.contains(remote.refname.as_str()) || tracked_by.contains_key(remote.refname.as_str());
        let in_scope = if skip {
            false
        } else {
            ranges
                .iter()
                .any(|r| matches!(r, DeleteRange::Remote(r) if r == "*" || r == remote.remote))
        };
        consider_probe(
            &mut probe,
            git,
            &bases,
            &ancestry_remotes,
            remote.refname.as_str(),
            skip || !in_scope,
            &mut merged,
        )?;
    }
    let _ = &mut pending;
    let _ = &mut tested;

    // Worktrees: which branch is checked out where, and which one is ours.
    let worktrees = parse_worktrees(&git.worktree_list().map_err(anyhow::Error::from)?);
    let current = repo.workdir().map(Path::new);
    let mut worktree_of: HashMap<&str, &Path> = HashMap::new();
    let mut head_branch: Option<&str> = None;
    for (path, refname) in &worktrees {
        let is_current = current.map(|c| c == path.as_path()).unwrap_or(false);
        if is_current {
            head_branch = Some(refname.as_str());
        } else {
            worktree_of.insert(refname.as_str(), path.as_path());
        }
    }

    let mut entries = Vec::new();
    for local in &locals {
        let upstream = upstream_of.get(local.refname.as_str());
        let merged = *merged.get(local.refname.as_str()).unwrap_or(&false);
        let class = match upstream {
            Some(upstream) => {
                let upstream_merged = *merged.get(&upstream.refname).unwrap_or(&false);
                if merged {
                    if upstream_merged {
                        Class::Merged
                    } else {
                        Class::Diverged(upstream.refname.clone())
                    }
                } else if upstream_merged {
                    Class::Stray
                } else {
                    Class::Stays
                }
            }
            None => {
                if merged {
                    Class::Merged
                } else {
                    Class::Stays
                }
            }
        };
        let base = bases
            .iter()
            .any(|b| b.local.as_deref() == Some(local.refname.as_str()));
        let tracks_base = bases
            .iter()
            .find(|b| Some(b.refname.as_str()) == upstream.map(|u| u.refname.as_str()))
            .map(|b| b.spec.clone());
        let worktree = worktree_of
            .get(local.refname.as_str())
            .map(|p| (*p).to_path_buf());
        let head = head_branch == Some(local.refname.as_str());
        entries.push(Entry {
            refname: local.refname.clone(),
            kind: Kind::Local {
                name: local.name.clone(),
                upstream: upstream.cloned(),
            },
            class,
            tracked: false,
            base,
            tracks_base,
            protected_by: None,
            worktree,
            head,
        });
    }
    for remote in &remotes {
        let tracked = tracked_by.contains_key(remote.refname.as_str());
        let owner = tracked_by.get(remote.refname.as_str()).copied();
        let merged = *merged.get(&remote.refname).unwrap_or(&false);
        let class = match owner {
            Some(local) => {
                if merged {
                    Class::Merged
                } else if *merged.get(local.refname.as_str()).unwrap_or(&false) {
                    Class::Diverged(local.refname.clone())
                } else {
                    Class::Stays
                }
            }
            None => {
                if merged {
                    Class::Merged
                } else {
                    Class::Stays
                }
            }
        };
        let base = base_refnames.contains(remote.refname.as_str());
        entries.push(Entry {
            refname: remote.refname.clone(),
            kind: Kind::Remote {
                remote: remote.remote.clone(),
                name: remote.name.clone(),
            },
            class,
            tracked,
            base,
            tracks_base: None,
            protected_by: None,
            worktree: None,
            head: false,
        });
    }

    for entry in &mut entries {
        entry.protected_by = protect(protected, entry);
    }

    let mut remote_local_heads = BTreeMap::new();
    for name in remote_names {
        remote_local_heads.insert(name.clone(), remote_head_target(repo, name, &remotes)?);
    }

    Ok(Scan {
        entries,
        bases,
        remote_heads,
        remote_local_heads,
    })
}

fn in_scope_local(upstream: &Option<&RemoteRef>, ranges: &[DeleteRange]) -> bool {
    if upstream.is_some() {
        any_of(ranges, &["merged-local", "stray", "merged-remote", "diverged"])
    } else {
        any_of(ranges, &["local"])
    }
}

fn ancestry_local_contains(map: &HashMap<String, HashSet<String>>, base: &str, refname: &str) -> bool {
    map.get(base).map(|s| s.contains(refname)).unwrap_or(false)
}

fn probe_direct(
    probe: &mut SquashProbe,
    git: &Git,
    base: &str,
    refname: &str,
) -> anyhow::Result<bool> {
    let output = git.cherry_pick_right_only(base, refname)?;
    Ok(crate::branch::cherry_pick_is_empty(&output))
}

fn consider_probe(
    probe: &mut SquashProbe,
    git: &Git,
    bases: &[Base],
    ancestry: &HashMap<String, HashSet<String>>,
    refname: &str,
    skip: bool,
    merged: &mut HashMap<String, bool>,
) -> anyhow::Result<()> {
    if skip || merged.contains_key(refname) {
        return Ok(());
    }
    let mut result = false;
    let mut pending: Vec<&Base> = Vec::new();
    for base in bases {
        if ancestry_local_contains(ancestry, &base.refname, refname) {
            result = true;
            break;
        }
        let direct = probe_direct(probe, git, &base.refname, refname)?;
        if direct {
            result = true;
            break;
        }
        pending.push(base);
    }
    merged.insert(refname.to_string(), result);
    let _ = pending;
    Ok(())
}

/// Names a branch is known by, in the order the protection check considers them.
fn names(entry: &Entry) -> Vec<String> {
    match &entry.kind {
        Kind::Local { name, .. } => vec![name.clone(), entry.refname.clone()],
        Kind::Remote { remote, name } => {
            vec![format!("{}/{}", remote, name), entry.refname.clone()]
        }
    }
}

fn protect(patterns: &[Pattern], entry: &Entry) -> Option<String> {
    if entry.base {
        return None;
    }
    for name in names(entry) {
        for pattern in patterns {
            if pattern.is_match(&name) {
                return Some(pattern.as_str().to_string());
            }
        }
    }
    None
}
