}

/// Is this delete range part of the configured set, regardless of the remote it names?
fn any_of(ranges: &[DeleteRange], wanted: &[&str]) -> bool {
    ranges.iter().any(|r| {
        wanted.iter().any(|w| match (r, *w) {
            (DeleteRange::MergedLocal, "merged-local") => true,
            (DeleteRange::Stray, "stray") => true,
            (DeleteRange::MergedRemote(_), "merged-remote") => true,
            (DeleteRange::Diverged(_), "diverged") => true,
            (DeleteRange::Local, "local") => true,
            (DeleteRange::Remote(_), "remote") => true,
            _ => false,
        })
    })
}

/// Does `ranges` contain a range that could ever apply to this branch?
fn in_scope(entry: &Entry, ranges: &[DeleteRange]) -> bool {
    let tracked_pair = matches!(entry.kind, Kind::Local { upstream: Some(_), .. })
        || (matches!(entry.kind, Kind::Remote { .. }) && entry.tracked);
    if tracked_pair {
        return any_of(ranges, &["merged-local", "stray", "merged-remote", "diverged"]);
    }
    match &entry.kind {
        Kind::Local { .. } => any_of(ranges, &["local"]),
        Kind::Remote { remote, .. } => ranges
            .iter()
            .any(|r| matches!(r, DeleteRange::Remote(r) if r == "*" || r == remote)),
    }
}

/// Run the whole scan.
#[allow(clippy::too_many_arguments)]
pub fn run(
    repo: &Repository,
    git: &Git,
    _config: &TrimConfig,
    explicit_bases: Option<&[String]>,
    protected: &[Pattern],
    remote_names: &[String],
    remote_heads: BTreeMap<String, anyhow::Result<String>>,
    ranges: &[DeleteRange],
) -> anyhow::Result<Scan> {
