                    if upstream_merged {
                        Class::Merged
                    } else {
                        Class::Diverged(upstream.refname.clone())
                    }
                } else if upstream_merged {
                    Class::Stray
                } else {
                    Class::Stays
                }
            }
            None => {
                if merged {
                    Class::Merged
                } else {
                    Class::Stays
                }
            }
        };
