            .iter()
            .any(|b| b.local.as_deref() == Some(local.refname.as_str()));
        let tracks_base = bases
            .iter()
            .find(|b| Some(b.refname.as_str()) == upstream.map(|u| u.refname.as_str()))
            .map(|b| b.spec.clone());
        let worktree = worktree_of
            .get(local.refname.as_str())
            .map(|p| (*p).to_path_buf());
        let head = head_branch == Some(local.refname.as_str());
        entries.push(Entry {
            refname: local.refname.clone(),
            kind: Kind::Local {
                name: local.name.clone(),
                upstream: upstream.cloned(),
            },
            class,
            tracked: false,
            base,
            tracks_base,
            protected_by: None,
            worktree,
            head,
        });
    }
    for remote in &remotes {
        let tracked = tracked_by.contains_key(remote.refname.as_str());
        let owner = tracked_by.get(remote.refname.as_str()).copied();
        let merged = *merged.get(&remote.refname).unwrap_or(&false);
        let class = match owner {
            Some(local) => {
                if merged {
                    Class::Merged
                } else if *merged.get(local.refname.as_str()).unwrap_or(&false) {
                    Class::Diverged(local.refname.clone())
                } else {
                    Class::Stays
                }
            }
            None => {
                if merged {
                    Class::Merged
                } else {
                    Class::Stays
                }
            }
        };
        let base = base_refnames.contains(remote.refname.as_str());
        entries.push(Entry {
            refname: remote.refname.clone(),
            kind: Kind::Remote {
                remote: remote.remote.clone(),
                name: remote.name.clone(),
            },
            class,
            tracked,
            base,
            tracks_base: None,
            protected_by: None,
            worktree: None,
            head: false,
        });
    }

    for entry in &mut entries {
        entry.protected_by = protect(protected, entry);
    }

    let mut remote_local_heads = BTreeMap::new();
    for name in remote_names {
        remote_local_heads.insert(name.clone(), remote_head_target(repo, name, &remotes)?);
    }

    Ok(Scan {
        entries,
        bases,
        remote_heads,
        remote_local_heads,
    })
}

fn in_scope_local(upstream: &Option<&RemoteRef>, ranges: &[DeleteRange]) -> bool {
    if upstream.is_some() {
        any_of(ranges, &["merged-local", "stray", "merged-remote", "diverged"])
    } else {
        any_of(ranges, &["local"])
    }
}

fn ancestry_local_contains(map: &HashMap<String, HashSet<String>>, base: &str, refname: &str) -> bool {
    map.get(base).map(|s| s.contains(refname)).unwrap_or(false)
}

fn probe_direct(
    probe: &mut SquashProbe,
    git: &Git,
    base: &str,
    refname: &str,
) -> anyhow::Result<bool> {
    let output = git.cherry_pick_right_only(base, refname)?;
    Ok(crate::branch::cherry_pick_is_empty(&output))
}

fn consider_probe(
    probe: &mut SquashProbe,
    git: &Git,
    bases: &[Base],
    ancestry: &HashMap<String, HashSet<String>>,
    refname: &str,
    skip: bool,
    merged: &mut HashMap<String, bool>,
) -> anyhow::Result<()> {
    if skip || merged.contains_key(refname) {
        return Ok(());
    }
    let mut result = false;
    let mut pending: Vec<&Base> = Vec::new();
    for base in bases {
        if ancestry_local_contains(ancestry, &base.refname, refname) {
            result = true;
            break;
        }
        let direct = probe_direct(probe, git, &base.refname, refname)?;
        if direct {
            result = true;
            break;
        }
        pending.push(base);
    }
    merged.insert(refname.to_string(), result);
    let _ = pending;
    Ok(())
}

/// Names a branch is known by, in the order the protection check considers them.
fn names(entry: &Entry) -> Vec<String> {
    match &entry.kind {
        Kind::Local { name, .. } => vec![name.clone(), entry.refname.clone()],
        Kind::Remote { remote, name } => {
            vec![format!("{}/{}", remote, name), entry.refname.clone()]
        }
    }
}

fn protect(patterns: &[Pattern], entry: &Entry) -> Option<String> {
    if entry.base {
        return None;
    }
    for name in names(entry) {
        for pattern in patterns {
            if pattern.is_match(&name) {
                return Some(pattern.as_str().to_string());
            }
        }
    }
    None
}
