s = s.replace('''    /// Is `refname` merged into `base`?
    pub fn is_merged(
        &mut self,
        git: &Git,
        base: &str,
        refname: &str,
        ancestry: &HashSet<String>,
    ) -> anyhow::Result<bool> {
        if ancestry.contains(refname) {
            return Ok(true);
        }
        let direct = git.cherry_pick_right_only(base, refname)?;
        if cherry_pick_is_empty(&direct) {
            return Ok(true);
        }
        let squash = self.squash_commit(base, refname)?;
        let squash = git.cherry_pick_right_only(base, &format!("{}", squash))?;
        Ok(cherry_pick_is_empty(&squash))
    }''','''    /// Is `refname` merged into `base`?
    ///
    /// Results are memoised per `(base, object)` pair: two branches pointing at the same commit
    /// only need one round trip.
    pub fn is_merged(
        &mut self,
        git: &Git,
        base: &str,
        refname: &str,
        ancestry: &HashSet<String>,
    ) -> anyhow::Result<Option<bool>> {
        if ancestry.contains(refname) {
            return Ok(Some(true));
        }
        let oid = self
            .repo
            .revparse_single(refname)?
            .peel_to_commit()?
            .id();
        if let Some(cached) = self.cache.get(&(oid, base.to_string())) {
            return Ok(Some(*cached));
        }
        let direct = git.cherry_pick_right_only(base, refname)?;
        if cherry_pick_is_empty(&direct) {
            self.cache.insert((oid, base.to_string()), true);
            return Ok(Some(true));
        }
        self.cache.insert((oid, base.to_string()), false);
        Ok(None)
    }

    /// Run the squash-merge probe for `refname` against `base`.
    pub fn probe_squash(
        &mut self,
        git: &Git,
        base: &str,
        refname: &str,
    ) -> anyhow::Result<bool> {
        let oid = self
            .repo
            .revparse_single(refname)?
            .peel_to_commit()?
            .id();
        let squash = self.squash_commit(base, refname)?;
        let output = git.cherry_pick_right_only(base, &format!("{}", squash))?;
        let merged = cherry_pick_is_empty(&output);
        if merged {
            self.cache.insert((oid, base.to_string()), true);
        }
        Ok(merged)
    }''')
open(p,'w').write(s)

