s = s.replace('''/// Test `refname` against every base: ancestry first, then the cherry-pick analysis.  Bases that
/// fail both are remembered for the squash-merge probe.
fn probe_merged(
    probe: &mut SquashProbe,
    git: &Git,
    bases: &[Base],
    ancestry: &HashMap<String, HashSet<String>>,
    refname: &str,
    merged: &mut HashMap<String, bool>,
    pending: &mut Vec<(String, usize)>,
) -> anyhow::Result<()> {
    if merged.contains_key(refname) {
        return Ok(());
    }
    let mut result = false;
    for (index, base) in bases.iter().enumerate() {
        if ancestry_contains(ancestry, &base.refname, refname) {
            result = true;
            break;
        }
        let output = match git.cherry_pick_right_only(&base.refname, refname) {
            Ok(output) => output,
            Err(err) => {
                eprintln!("DBG5 cherry error refname={} {}", refname, err);
                return Err(anyhow::Error::from(err));
            }
        };
        if crate::branch::cherry_pick_is_empty(&output) {
            result = true;
            break;
        }
        pending.push((refname.to_string(), index));
    }
    eprintln!("DBG3 refname={} result={}", refname, result);
    merged.insert(refname.to_string(), result);
    Ok(())
}''','''/// Test `refname` against every base: ancestry first, then the cherry-pick analysis.  Bases that
/// fail both are remembered for the squash-merge probe.
fn probe_merged(
    probe: &mut SquashProbe,
    _git: &Git,
    bases: &[Base],
    ancestry: &HashMap<String, HashSet<String>>,
    refname: &str,
    merged: &mut HashMap<String, bool>,
    pending: &mut Vec<(String, usize)>,
) -> anyhow::Result<()> {
    if merged.contains_key(refname) {
        return Ok(());
    }
    let mut result = false;
    for (index, base) in bases.iter().enumerate() {
        if let Some(merged) = probe.is_merged(_git, &base.refname, refname, &ancestry[&base.refname])? {
            if merged {
                result = true;
            }
            break;
        }
        pending.push((refname.to_string(), index));
    }
    merged.insert(refname.to_string(), result);
    Ok(())
}''')
s = s.replace('''    // Phase 2: the squash-merge probes for everything the cherry-pick analysis could not resolve.
    for (refname, index) in pending {
        let base = &bases[index];
        let squash = probe.squash_commit(&base.refname, &refname)?;
        let output = git.cherry_pick_right_only(&base.refname, &format!("{}", squash))?;
        if crate::branch::cherry_pick_is_empty(&output) {
            merged.insert(refname.clone(), true);
        }
    }''','''    // Phase 2: the squash-merge probes for everything the cherry-pick analysis could not resolve.
    for (refname, index) in pending {
        let base = &bases[index];
        if probe.probe_squash(git, &base.refname, &refname)? {
            merged.insert(refname.clone(), true);
        }
    }''')
open(p,'w').write(s)
