new = '''    // Phase 1: the cherry-pick analysis for every branch in scope.  Base branches and the branches
    // that track them are never probed.  Verdicts are memoised per (commit, base) pair so that two
    // branches pointing at the same commit share one round trip.
    let mut probe = SquashProbe::new(repo)?;
    let mut verdict: HashMap<(git2::Oid, String), bool> = HashMap::new();
    let mut pending: Vec<(String, usize)> = Vec::new();
    let mut considered: Vec<String> = Vec::new();

    let mut probe_ref = |probe: &mut SquashProbe,
                         refname: &str,
                         ancestry: &HashMap<String, HashSet<String>>,
                         verdict: &mut HashMap<(git2::Oid, String), bool>,
                         pending: &mut Vec<(String, usize)>|
     -> anyhow::Result<()> {
        let oid = probe.commit_oid(refname)?;
        for (index, base) in bases.iter().enumerate() {
            let key = (oid, base.refname.clone());
            if let Some(cached) = verdict.get(&key) {
                let _ = cached;
                continue;
            }
            if ancestry
                .get(&base.refname)
                .map(|s| s.contains(refname))
                .unwrap_or(false)
            {
                verdict.insert(key, true);
                continue;
            }
            let merged = probe.cherry_pick(git, &base.refname, refname)?;
            verdict.insert(key, merged);
            if !merged {
                pending.push((refname.to_string(), index));
            }
        }
        considered.push(refname.to_string());
        Ok(())
    };

    for local in &locals {
        let upstream = upstream_of.get(local.refname.as_str());
        let skip = base_refnames.contains(local.refname.as_str())
            || upstream
                .map(|u| base_refnames.contains(u.refname.as_str()))
                .unwrap_or(false);
        if !skip && in_scope_local(upstream, ranges) {
            probe_ref(
                &mut probe,
                local.refname.as_str(),
                &ancestry_locals,
                &mut verdict,
                &mut pending,
            )?;
        }
        if let Some(upstream) = upstream {
            let skip = base_refnames.contains(upstream.refname.as_str())
                || base_refnames.contains(local.refname.as_str());
            if !skip {
                probe_ref(
                    &mut probe,
                    upstream.refname.as_str(),
                    &ancestry_remotes,
                    &mut verdict,
                    &mut pending,
                )?;
            }
        }
    }
    for remote in &remotes {
        let skip = base_refnames.contains(remote.refname.as_str())
            || tracked_by.contains_key(remote.refname.as_str());
        let in_scope = ranges
            .iter()
            .any(|r| matches!(r, DeleteRange::Remote(r) if r.as_str() == "*" || r.as_str() == remote.remote));
        if !skip && in_scope {
            probe_ref(
                &mut probe,
                remote.refname.as_str(),
                &ancestry_remotes,
                &mut verdict,
                &mut pending,
            )?;
        }
    }

    // Phase 2: the squash-merge probes for everything the cherry-pick analysis could not resolve.
    for (refname, index) in pending {
        let base = &bases[index];
        if probe.probe_squash(git, &base.refname, &refname)? {
            let oid = probe.commit_oid(&refname)?;
            verdict.insert((oid, base.refname.clone()), true);
        }
    }

    let merged_of = |probe: &SquashProbe, refname: &str| -> anyhow::Result<bool> {
        let oid = probe.commit_oid(refname)?;
        Ok(bases.iter().any(|b| {
            verdict
                .get(&(oid, b.refname.clone()))
                .copied()
                .unwrap_or(false)
        }))
    };

    let mut merged: HashMap<String, bool> = HashMap::new();
    for local in &locals {
        merged.insert(local.refname.clone(), merged_of(&probe, &local.refname)?);
    }
    for remote in &remotes {
        merged.insert(remote.refname.clone(), merged_of(&probe, &remote.refname)?);
    }
    let _ = considered;

'''
